// Single 1000-based byte formatter. Replaces the divergent copies in
// FileMessageContent.fileSize and FileSizeLimitModal.formatSize (L35).
export const formatBytes = (bytes: number): string => {
  // A malformed message `extra` leaves bytes undefined/NaN; without this guard
  // every `<` comparison is false and the GB branch renders the literal 'NaNGB'.
  if (!Number.isFinite(bytes) || bytes < 0) return ''
  if (bytes < 1000) return bytes + 'B'
  if (bytes < 1_000_000) return (bytes / 1000).toFixed(1) + 'KB'
  if (bytes < 1_000_000_000) return (bytes / 1_000_000).toFixed(1) + 'MB'
  return (bytes / 1_000_000_000).toFixed(1) + 'GB'
}
