import { computed, ref } from 'vue'
import { imageCache } from '../runtime/caches'
import { getSignedUrl } from '../runtime/signedUrlStore'
import { useImkitStore } from '../stores/imkit'

/** Minimum ID length required for generating a meaningful fallback filename */
const MIN_ID_LENGTH_FOR_FILENAME = 8

/** Common MIME types used in media download */
export const MIME_TYPES = {
  IMAGE_JPEG: 'image/jpeg',
  VIDEO_MP4: 'video/mp4',
  OCTET_STREAM: 'application/octet-stream'
} as const

export interface DownloadOptions {
  url: string
  fileName?: string
  fallbackId?: string
  mimeType?: string
  cachedDataUrl?: string
  /** 使用 signed URL 下載（適合大檔案如影片） */
  useSignedUrl?: boolean
  /** 已取得的 signed URL（如果有的話） */
  signedUrl?: string
}

const parseDataUrl = (
  dataUrl: string
): { mimeType: string; base64: string; fileExtension: string } | null => {
  if (!dataUrl?.startsWith('data:')) return null
  const [meta, base64] = dataUrl.split(',', 2)
  if (!meta || !base64) return null
  const mimeType = meta.split(';')[0].replace('data:', '')
  const fileExtension = mimeType.split('/')[1] || 'bin'
  return { mimeType, base64, fileExtension }
}

/**
 * Whether `href` resolves to a different origin than the current page.
 * The <a download> attribute is only honoured for same-origin (and blob:/data:)
 * targets — a cross-origin remote URL just navigates the SPA instead.
 */
const isCrossOrigin = (href: string): boolean => {
  try {
    return new URL(href, window.location.href).origin !== window.location.origin
  } catch {
    return false
  }
}

const getFileNameFromUrl = (url: string): string | null => {
  try {
    const parsedUrl = new URL(url, window.location.href)
    const last = parsedUrl.pathname.split('/').filter(Boolean).pop()
    if (!last) return null
    const decoded = decodeURIComponent(last)
    const dot = decoded.lastIndexOf('.')
    if (dot > 0) return decoded.slice(0, dot)
    return decoded
  } catch {
    return null
  }
}

/**
 * Download file using fetch and trigger browser download
 */
const downloadFileInBrowser = async (
  signedUrl: string,
  fileName: string,
  fileExtension: string
): Promise<void> => {
  try {
    const response = await fetch(signedUrl)
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`)
    }
    const blob = await response.blob()
    const blobUrl = URL.createObjectURL(blob)

    const a = document.createElement('a')
    a.href = blobUrl
    a.download = `${fileName}.${fileExtension}`
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)

    // Revoke after the browser has committed the download. A fixed 1s timer can
    // abort large/slow downloads; revoke on the next tick is too eager. Use a
    // generous window — the blob is GC-eligible once revoked, and the download
    // stream already holds its own reference after click().
    setTimeout(() => URL.revokeObjectURL(blobUrl), 60_000)
  } catch (error) {
    console.error('[useMediaDownload] Browser download failed:', error)
    // Fallback: open signed URL directly (let browser handle it).
    // noopener,noreferrer severs window.opener and the referrer.
    const opened = window.open(signedUrl, '_blank', 'noopener,noreferrer')
    // A null return means the popup was blocked: the user now has neither a
    // download nor an open tab. Surface it instead of failing silently.
    if (opened === null) {
      throw new Error('Download popup blocked', { cause: error })
    }
  }
}

export function useMediaDownload() {
  const imkit = useImkitStore()
  const isDownloading = ref(false)
  const downloadProgresses = computed(() => imkit.downloadProgresses)

  const download = async (options: DownloadOptions): Promise<void> => {
    if (isDownloading.value) return
    isDownloading.value = true

    const {
      url,
      fallbackId,
      mimeType: defaultMimeType,
      cachedDataUrl,
      useSignedUrl,
      signedUrl
    } = options

    try {
      // Determine file name
      const fallbackName =
        fallbackId && fallbackId.length >= MIN_ID_LENGTH_FOR_FILENAME
          ? `media-${fallbackId.slice(0, MIN_ID_LENGTH_FOR_FILENAME)}`
          : 'media'
      // Strip extension from fileName if it has one
      const stripExtension = (name: string): string => {
        const dot = name.lastIndexOf('.')
        return dot > 0 ? name.slice(0, dot) : name
      }

      const fileName = options.fileName
        ? stripExtension(options.fileName)
        : getFileNameFromUrl(url) || fallbackName

      // Check for cached data URL (for images)
      const cachedHref =
        cachedDataUrl || imageCache.get(url) || getSignedUrl(url)

      // Signed URL download mode (for videos and large files)
      if (useSignedUrl && signedUrl) {
        const mimeType = defaultMimeType || MIME_TYPES.OCTET_STREAM
        const fileExtension = mimeType.split('/')[1] || 'bin'
        await downloadFileInBrowser(signedUrl, fileName, fileExtension)
        return
      }

      // Browser download
      const href = cachedHref || url

      const parsed = cachedHref ? parseDataUrl(cachedHref) : null
      const fileExtension =
        parsed?.fileExtension || defaultMimeType?.split('/')[1]

      // A cross-origin, non-data: href can't be downloaded by a bare
      // <a download> — the browser ignores the download attribute and navigates
      // the SPA away. Pull it via fetch -> blob -> blob: anchor instead so the
      // download actually happens and app state survives.
      if (!href.startsWith('data:') && isCrossOrigin(href)) {
        await downloadFileInBrowser(href, fileName, fileExtension || 'bin')
        return
      }

      const a = document.createElement('a')
      a.href = href
      a.download = fileExtension ? `${fileName}.${fileExtension}` : fileName
      a.click()
    } finally {
      isDownloading.value = false
    }
  }

  return {
    isDownloading,
    downloadProgresses,
    download
  }
}
