<script setup lang="ts">
import { useVfm } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'
import Folder from './../classes/folder'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

const vfm = useVfm()
const props = defineProps<{ folder: Folder }>()
const imkit = useImkitStore()

const cancel = () => vfm.closeAll()
const confirm = () => {
  imkit.removeFolder(props.folder.id)
  vfm.closeAll()
}
</script>

<template>
  <ConfirmDialogShell
    :title="$t('confirmToDeleteFolder')"
    :cancel-label="$t('cancel')"
    :confirm-label="$t('confirm')"
    confirm-test-id="delete-folder-confirm-action"
    @cancel="cancel"
    @confirm="confirm"
  >
    {{ $t('deleteFolderConfirmDescription', { name: props.folder.name }) }}
  </ConfirmDialogShell>
</template>
