<script setup lang="ts">
import type MarkdownIt from 'markdown-it'
import MarkdownRender from 'vue-renderer-markdown'
import { AIStreamingMessage } from '../classes/message'
const props = defineProps<{ message: AIStreamingMessage }>()

const BAD_URL_PROTOCOL = /^(?:vbscript|javascript|file|data):/i
const SAFE_DATA_URL = /^data:image\/(?:gif|png|jpe?g|webp);/i
const isUnsafeUrl = (url: string) => {
  const value = String(url).trim().toLowerCase()
  return BAD_URL_PROTOCOL.test(value) && !SAFE_DATA_URL.test(value)
}

// vue-renderer-markdown builds its markdown-it with html:true and renders raw
// HTML tokens via innerHTML, and its LinkNode reads the parsed href directly,
// bypassing markdown-it's validateLink. Prompt-injectable AI output could thus
// inject live markup (<script>/<img onerror>/<iframe>/...) or a clickable
// [text](javascript:...) link. Harden the markdown-it instance the lib uses:
//   - html:false so raw HTML is escaped/dropped instead of executed;
//   - an inline.ruler2 pass that rewrites dangerous-protocol link hrefs to '#'
//     (ruler2 runs in the parseInline path the lib uses; the core ruler does not).
// Defined once (stable identity) rather than inline in the template, because the
// library wraps it in a computed and a fresh function per render would re-run it
// on every streamed token.
const hardenMarkdown = (md: MarkdownIt) => {
  md.set({ html: false })
  md.inline.ruler2.push('imkit_safe_links', (state) => {
    for (const token of state.tokens) {
      if (token.type !== 'link_open' || !token.attrs) continue
      for (const attr of token.attrs) {
        if (attr[0] === 'href' && isUnsafeUrl(attr[1])) attr[1] = '#'
      }
    }
    // ruler2 is a post-process pass; the return is ignored by the parser.
    return false
  })
  return md
}
</script>

<template>
  <MarkdownRender
    class="prose wrap-break-word select-none dark:prose-invert pointer-fine:select-text prose-headings:mt-0 prose-p:leading-5.5 prose-ol:my-0"
    :content="props.message.text"
    :custom-markdown-it="hardenMarkdown"
    :typewriter-effect="true"
  />
</template>
<style scoped>
/* MarkdownRender wraps content in node-spacer/node-slot divs, which prevents
   Tailwind prose's `:first-child { margin-top: 0 }` from reaching the <p>.
   Manually zero out the first node's top margin to match TextMessageContent. */
:deep([data-node-index='0'] > .node-content > :first-child) {
  margin-top: 0;
}

/* When there's only one node (spacer, slot[0], spacer = 3 children),
   also zero out the bottom margin to match prose :last-child behavior. */
:deep(
  [data-node-index='0']:nth-child(2):nth-last-child(2)
    > .node-content
    > :last-child
) {
  margin-bottom: 0;
}

/* MarkdownRender renders <pre>    <code>...</code>\n  </pre> with extra
   whitespace text nodes that each render as a visible line. Collapse them
   with line-height: 0 so the code block height matches TextMessageContent. */
:deep(pre) {
  line-height: 0;
}
:deep(pre code) {
  line-height: 1.7142857;
}

/* In prose, :last-child { margin-bottom: 0 } applies to direct children.
   MarkdownRender nests <pre> inside node-slot/node-content, so the prose
   rule doesn't reach it. Zero out mb on <pre> in the last node-slot. */
:deep(.node-slot:nth-last-child(2) > .node-content > pre) {
  margin-bottom: 0;
}

/* MarkdownRender adds my-2 (7.5px) to list items, but TextMessageContent
   uses prose + scoped li { margin: 0 }. Match that behavior. */
:deep(li) {
  margin-top: 0;
  margin-bottom: 0;
}
:deep(ol > li)::marker,
:deep(ul > li)::marker {
  color: inherit;
}

/* MarkdownRender wraps li text in <p>, adding extra marginBottom.
   TextMessageContent li has bare text with no inner <p> margins. */
:deep(li p) {
  margin-top: 0;
  margin-bottom: 0;
}

/* `--color-accent-vivid` is blue-500 in light and blue-400 in dark — the exact
   pair this rule used to hand-write. The token flips itself, so no dark-mode
   rule is needed. Never reintroduce one as `:global(.dark) :deep(...)`: that
   form compiles to a bare `.dark { ... }` selector (see ReactionList.vue). */
:deep(a) {
  color: var(--color-accent-vivid);
  text-decoration: underline;
}
</style>
