import { computed, ref, type CSSProperties, type Ref } from 'vue'

type Point = {
  x: number
  y: number
}

type PinchStart = {
  distance: number
  midpoint: Point
  scale: number
  translation: Point
}

type Tap = Point & {
  at: number
}

const distanceBetween = (first: Point, second: Point) =>
  Math.hypot(second.x - first.x, second.y - first.y)

const midpointBetween = (first: Point, second: Point): Point => ({
  x: (first.x + second.x) / 2,
  y: (first.y + second.y) / 2
})

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value))

export const useImageZoom = (
  containerRef: Ref<HTMLElement | null>,
  options: { maxScale?: number; doubleTapScale?: number } = {}
) => {
  const maxScale = options.maxScale ?? 4
  const doubleTapScale = options.doubleTapScale ?? 2
  const scale = ref(1)
  const translateX = ref(0)
  const translateY = ref(0)
  const isInteracting = ref(false)

  const pointers = new Map<number, Point>()
  const pointerStarts = new Map<number, Point>()
  let dragStart: Point | null = null
  let dragStartTranslation: Point = { x: 0, y: 0 }
  let pinchStart: PinchStart | null = null
  let gestureHadMultiplePointers = false
  let lastTouchTap: Tap | null = null
  let lastTouchZoomAt = 0

  const getContainerRect = () =>
    containerRef.value?.getBoundingClientRect() ?? null

  const getPanLimits = (nextScale: number) => {
    const container = containerRef.value
    const rect = getContainerRect()
    const image = container?.querySelector('img')

    if (!container || !rect || !image) return { x: 0, y: 0 }

    const imageWidth = image.offsetWidth || image.clientWidth
    const imageHeight = image.offsetHeight || image.clientHeight

    return {
      x: Math.max(0, (imageWidth * nextScale - rect.width) / 2),
      y: Math.max(0, (imageHeight * nextScale - rect.height) / 2)
    }
  }

  const setTranslation = (x: number, y: number, nextScale = scale.value) => {
    const limits = getPanLimits(nextScale)
    translateX.value = clamp(x, -limits.x, limits.x)
    translateY.value = clamp(y, -limits.y, limits.y)
  }

  const reset = () => {
    pointers.clear()
    pointerStarts.clear()
    dragStart = null
    pinchStart = null
    gestureHadMultiplePointers = false
    lastTouchTap = null
    scale.value = 1
    translateX.value = 0
    translateY.value = 0
    isInteracting.value = false
  }

  const zoomAt = (clientX: number, clientY: number, nextScale: number) => {
    const rect = getContainerRect()
    const clampedScale = clamp(nextScale, 1, maxScale)

    if (!rect || clampedScale === 1) {
      scale.value = clampedScale
      setTranslation(0, 0, clampedScale)
      return
    }

    const localX = clientX - rect.left - rect.width / 2
    const localY = clientY - rect.top - rect.height / 2
    const ratio = clampedScale / scale.value
    const nextX = localX - (localX - translateX.value) * ratio
    const nextY = localY - (localY - translateY.value) * ratio

    scale.value = clampedScale
    setTranslation(nextX, nextY, clampedScale)
  }

  const toggleZoom = (clientX: number, clientY: number) => {
    if (scale.value > 1) {
      reset()
      return
    }
    zoomAt(clientX, clientY, doubleTapScale)
  }

  const beginDragFrom = (point: Point) => {
    dragStart = point
    dragStartTranslation = {
      x: translateX.value,
      y: translateY.value
    }
  }

  const beginPinch = () => {
    const [first, second] = [...pointers.values()]
    if (!first || !second) return

    gestureHadMultiplePointers = true
    pinchStart = {
      distance: Math.max(1, distanceBetween(first, second)),
      midpoint: midpointBetween(first, second),
      scale: scale.value,
      translation: {
        x: translateX.value,
        y: translateY.value
      }
    }
  }

  const onPointerDown = (event: PointerEvent) => {
    if (!event.isPrimary && event.pointerType === 'mouse') return

    const point = { x: event.clientX, y: event.clientY }
    pointers.set(event.pointerId, point)
    pointerStarts.set(event.pointerId, point)
    isInteracting.value = true

    const target = event.currentTarget as HTMLElement | null
    if (target?.setPointerCapture) {
      target.setPointerCapture(event.pointerId)
    }

    if (pointers.size === 2) {
      beginPinch()
    } else if (pointers.size === 1) {
      beginDragFrom(point)
    }

    if (event.pointerType !== 'mouse' || scale.value > 1) {
      event.preventDefault()
    }
  }

  const onPointerMove = (event: PointerEvent) => {
    if (!pointers.has(event.pointerId)) return

    const point = { x: event.clientX, y: event.clientY }
    pointers.set(event.pointerId, point)

    if (pointers.size >= 2 && pinchStart) {
      const [first, second] = [...pointers.values()]
      if (!first || !second) return

      const currentMidpoint = midpointBetween(first, second)
      const nextScale = clamp(
        pinchStart.scale *
          (distanceBetween(first, second) / pinchStart.distance),
        1,
        maxScale
      )
      const rect = getContainerRect()

      if (!rect) return

      const startLocalX = pinchStart.midpoint.x - rect.left - rect.width / 2
      const startLocalY = pinchStart.midpoint.y - rect.top - rect.height / 2
      const currentLocalX = currentMidpoint.x - rect.left - rect.width / 2
      const currentLocalY = currentMidpoint.y - rect.top - rect.height / 2
      const scaleRatio = nextScale / pinchStart.scale

      scale.value = nextScale
      setTranslation(
        currentLocalX - (startLocalX - pinchStart.translation.x) * scaleRatio,
        currentLocalY - (startLocalY - pinchStart.translation.y) * scaleRatio,
        nextScale
      )
    } else if (pointers.size === 1 && dragStart && scale.value > 1) {
      setTranslation(
        dragStartTranslation.x + point.x - dragStart.x,
        dragStartTranslation.y + point.y - dragStart.y
      )
    }

    if (event.pointerType !== 'mouse' || scale.value > 1) {
      event.preventDefault()
    }
  }

  const finishPointer = (event: PointerEvent) => {
    const start = pointerStarts.get(event.pointerId)
    const end = {
      x: event.clientX,
      y: event.clientY
    }
    const isTouchTap =
      event.type === 'pointerup' &&
      event.pointerType === 'touch' &&
      !gestureHadMultiplePointers &&
      Boolean(start) &&
      distanceBetween(start!, end) < 10

    pointers.delete(event.pointerId)
    pointerStarts.delete(event.pointerId)

    const target = event.currentTarget as HTMLElement | null
    if (target?.hasPointerCapture?.(event.pointerId)) {
      target.releasePointerCapture(event.pointerId)
    }

    if (pointers.size === 1) {
      const remainingPoint = [...pointers.values()][0]
      if (remainingPoint) beginDragFrom(remainingPoint)
      pinchStart = null
    } else if (pointers.size === 0) {
      dragStart = null
      pinchStart = null
      isInteracting.value = false

      if (scale.value === 1) setTranslation(0, 0)

      if (isTouchTap) {
        const now = Date.now()
        if (
          lastTouchTap &&
          now - lastTouchTap.at <= 300 &&
          distanceBetween(lastTouchTap, end) <= 32
        ) {
          toggleZoom(end.x, end.y)
          lastTouchTap = null
          lastTouchZoomAt = now
        } else {
          lastTouchTap = { ...end, at: now }
        }
      }

      gestureHadMultiplePointers = false
    }

    if (event.pointerType !== 'mouse' || scale.value > 1) {
      event.preventDefault()
    }
  }

  const onDoubleClick = (event: MouseEvent) => {
    event.preventDefault()
    if (Date.now() - lastTouchZoomAt < 500) return
    toggleZoom(event.clientX, event.clientY)
  }

  const imageStyle = computed<CSSProperties>(() => ({
    transform: `translate3d(${translateX.value}px, ${translateY.value}px, 0) scale(${scale.value})`,
    transformOrigin: 'center center',
    transition: isInteracting.value ? 'none' : 'transform 180ms ease',
    willChange: 'transform'
  }))

  return {
    imageStyle,
    isInteracting,
    isZoomed: computed(() => scale.value > 1),
    onDoubleClick,
    onPointerCancel: finishPointer,
    onPointerDown,
    onPointerMove,
    onPointerUp: finishPointer,
    reset,
    scale,
    translateX,
    translateY
  }
}
