<script setup lang="ts">
import { Info, Pencil, X } from 'lucide-vue-next'
import { computed, ref, watch } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'
import { deriveTagPalette, TAG_PRESET_COLORS } from '../utils/tagColor'

const PRESET_COLORS = TAG_PRESET_COLORS

/** Chip fill/label, derived per theme from the stored hex. See
 * src/utils/tagColor.ts and the `.tag-chip` rule in src/style.css — the
 * chip reads `--tag-bg`/`--tag-fg` in light mode and
 * `--tag-bg-dark`/`--tag-fg-dark` in dark mode via that rule, so both
 * pairs are set here and the theme switch itself lives in CSS. */
const tagChipStyle = (tagHex: string) => {
  const palette = deriveTagPalette(tagHex)
  return {
    '--tag-bg': palette.lightBg,
    '--tag-fg': palette.lightFg,
    '--tag-bg-dark': palette.darkBg,
    '--tag-fg-dark': palette.darkFg
  }
}

const MODES = {
  ADD: 'add',
  EDIT: 'edit'
}

const vfm = useVfm()
const props = defineProps<{ roomId: string }>()
const imkit = useImkitStore()
const tags = ref<string[]>([])
const tagColors = ref<{ [tag: string]: string }>({})
const tag = ref('')
const color = ref(PRESET_COLORS.red)
const currentMode = ref(MODES.ADD)
const editingTag = ref('')
const customHexColor = ref('')

const isDuplicatedTag = computed(() => {
  if (!tag.value.trim()) {
    return false
  }

  if (currentMode.value === MODES.EDIT && tag.value === editingTag.value) {
    return false
  }

  const isTagExists = tags.value.includes(tag.value)
  return isTagExists
})
const isInAddMode = computed(() => currentMode.value === MODES.ADD)

const isValidHex = (hex: string): boolean => {
  return /^#([0-9A-Fa-f]{3}){1,2}$/.test(hex)
}

const confirm = (roomId: string) => {
  imkit.updateRoomPrefs({
    roomId,
    prefs: {
      tags: tags.value,
      tagColors: tagColors.value
    }
  })
}
const room = imkit.rooms[props.roomId]
if (room.pref) {
  tags.value = [...(room.pref.tags || [])]
  tagColors.value = { ...(room.pref.tagColors || {}) }
}
const add = () => {
  const trimmed = tag.value.trim()
  if (!trimmed) return
  if (!isValidHex(color.value)) return
  // A half-typed or malformed hex blocks the add, and the field shows its
  // format warning. This used to happen as a side effect: clicking the swatch
  // assigned the raw text to `color`, so an invalid value poisoned the
  // selection and the guard above caught it. The swatch is a colour picker
  // now and the field only applies values that parse, so the guard has to be
  // stated rather than inherited — otherwise typing garbage would silently
  // add the tag in whatever colour was selected before.
  if (customHexColor.value && !isValidHex(customHexColor.value)) return

  if (currentMode.value === MODES.EDIT) {
    const oldTag = editingTag.value
    tags.value = tags.value.filter((t) => t !== oldTag)
    delete tagColors.value[oldTag]

    if (!tags.value.includes(trimmed)) {
      tags.value.push(trimmed)
    }
    tagColors.value[trimmed] = color.value

    currentMode.value = MODES.ADD
    editingTag.value = ''
  } else {
    if (tags.value.length >= 5) {
      return
    }
    if (!tags.value.includes(trimmed)) {
      tags.value.push(trimmed)
    }
    tagColors.value[trimmed] = color.value
  }

  tag.value = ''
  color.value = PRESET_COLORS.red
  customHexColor.value = ''
  confirm(props.roomId)
}

const onClickEditTag = (editTag: string) => {
  currentMode.value = MODES.EDIT
  editingTag.value = editTag
  tag.value = editTag
  const tagColor = tagColors.value[editTag]
  color.value = tagColor

  const isPresetColor = Object.values(PRESET_COLORS).includes(tagColor)
  customHexColor.value = isPresetColor ? '' : tagColor
}

const cancelEdit = () => {
  currentMode.value = MODES.ADD
  editingTag.value = ''
  tag.value = ''
  color.value = PRESET_COLORS.red
  customHexColor.value = ''
}

const onClickRemoveTag = (deleteTag: string) => {
  tags.value = tags.value.filter((t) => t !== deleteTag)
  delete tagColors.value[deleteTag]
  confirm(props.roomId)
}

// Typing a valid hex selects it. The swatch used to be the control that
// applied what you typed — click it and `color = customHexColor` — which is
// why it read as a button. Now that the swatch opens a picker instead, the
// text field has to apply itself, or a typed hex would never take effect.
watch(customHexColor, (value) => {
  if (isValidHex(value)) {
    color.value = value
  }
})

// Choosing a preset abandons the custom field. Without this, half-typed text
// left in that field kept blocking the save via the guard in add() — the user
// had moved on to a preset, the button looked enabled, clicking it did
// nothing, and the only feedback was a warning on a field they had stopped
// using. Found in review, and exactly the shape of a guard that also
// suppresses a legitimate path.
const selectPreset = (preset: string) => {
  color.value = preset
  customHexColor.value = ''
}

const onPickCustomColour = (event: Event) => {
  const picked = (event.target as HTMLInputElement).value
  customHexColor.value = picked
  color.value = picked
}

const onClickSelectTag = (selectedTag: string) => {
  tag.value = selectedTag
  color.value = tagColors.value[selectedTag]
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-surface rounded-lg border border-border p-5 flex flex-col gap-3 max-w-[360px] w-full shadow-raised"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div
      class="mb-1 flex w-full items-center justify-between text-xl font-semibold text-content"
    >
      <p>
        {{ isInAddMode ? $t('manageTag') : $t('editTag') }}
        <span v-if="isInAddMode" class="text-content-muted"
          >· {{ room.displayName }}</span
        >
      </p>
      <button
        class="flex cursor-pointer items-center justify-center"
        @click="vfm.closeAll()"
      >
        <X class="h-6 w-6" />
      </button>
    </div>
    <p v-if="isInAddMode" class="-mt-2 text-xs text-content-muted">
      {{ $t('tagsDialogExplain') }}
    </p>
    <div v-if="tags.length > 0 && isInAddMode">
      <label class="mb-2 block text-xs font-semibold text-content-muted">{{
        $t('appliedTagsCount', { n: tags.length })
      }}</label>
      <div class="flex flex-wrap gap-1.5">
        <div
          v-for="tg in tags"
          :key="tg"
          class="tag-chip flex items-center gap-1 rounded-full py-1 pr-2 pl-3 text-xs font-semibold transition-colors focus:ring-2 focus:ring-offset-2 focus:outline-none"
          :style="tagChipStyle(tagColors[tg])"
          @click="onClickSelectTag(tg)"
        >
          {{ tg }}
          <button
            class="ml-1 cursor-pointer hover:opacity-70"
            @click.stop="onClickEditTag(tg)"
          >
            <Pencil class="h-3 w-3" />
          </button>
          <button
            class="cursor-pointer hover:opacity-70"
            @click.stop="onClickRemoveTag(tg)"
          >
            <X class="h-3 w-3" />
          </button>
        </div>
      </div>
    </div>
    <div>
      <label
        class="mb-2 flex items-center gap-1 text-xs font-semibold text-content-muted"
      >
        <!-- No + icon here: this is a field label, not an actionable row.
             AddToFolderModal's 「建立新資料夾…」 keeps one because that IS a
             button you click. -->
        {{ isInAddMode ? $t('createNewTagPrompt') : $t('editTag') }}
      </label>
      <div
        :class="[
          'flex items-center gap-2 rounded-md border bg-surface px-3.5 py-2.5 focus-within:ring-2',
          isDuplicatedTag
            ? 'border-danger focus-within:ring-danger'
            : 'border-border focus-within:border-accent focus-within:ring-accent-subtle'
        ]"
      >
        <input
          v-model="tag"
          type="text"
          maxlength="12"
          class="grow bg-transparent text-base text-content placeholder-content-subtle outline-none"
          :placeholder="isInAddMode ? $t('createTag') : $t('editTag')"
          :disabled="tags.length >= 5 && isInAddMode"
        />
        <span class="shrink-0 text-xs text-content-muted"
          >{{ tag.length }}/12</span
        >
      </div>
    </div>
    <div v-if="tags.length < 5 || !isInAddMode" class="mt-3">
      <label class="mb-2 block text-xs font-semibold text-content-muted">{{
        $t('chooseColor')
      }}</label>
      <!--
        The hairline border is unconditional, not part of the selected branch.
        A swatch is a raw preset colour painted on the modal's own fill, so the
        lightest presets have almost no edge of their own and read as a gap in
        the row rather than a colour you can choose. The selected ring sits
        outside the border via ring-offset, so the two do not collide.
      -->
      <div class="flex flex-wrap gap-2">
        <button
          v-for="c in Object.keys(PRESET_COLORS)"
          :key="c"
          class="size-8 cursor-pointer rounded-md border border-border transition-all"
          :class="
            color === PRESET_COLORS[c]
              ? 'ring-2 ring-accent ring-offset-2 ring-offset-surface'
              : ''
          "
          :style="{ backgroundColor: PRESET_COLORS[c] }"
          @click="selectPreset(PRESET_COLORS[c])"
        />
      </div>
    </div>
    <div v-if="tags.length < 5 || !isInAddMode">
      <div class="mt-3 flex items-center gap-2">
        <!--
          A real colour input, not a button. It rendered a rainbow gradient —
          which reads as "click to pick any colour" — but its handler was
          `color = customHexColor`, so with the hex field empty a click set the
          selection to an empty string and nothing happened. The affordance
          promised something the control could not do.

          The native input is stretched over the swatch at zero opacity so the
          swatch itself stays the visible control while the OS picker is what
          actually opens; picking writes through to the hex field, so the two
          can no longer disagree.
        -->
        <label
          class="relative size-8 flex-shrink-0 cursor-pointer overflow-hidden rounded-md border transition-all"
          :class="
            color === customHexColor && isValidHex(customHexColor)
              ? 'ring-2 ring-accent ring-offset-2 ring-offset-surface'
              : 'border-border-strong'
          "
          :style="
            isValidHex(customHexColor)
              ? { backgroundColor: customHexColor }
              : {
                  background:
                    'linear-gradient(135deg, #ef4444, #22c55e, #3b82f6)'
                }
          "
        >
          <input
            type="color"
            data-testid="tag-custom-colour"
            class="absolute inset-0 h-full w-full cursor-pointer opacity-0"
            :value="isValidHex(customHexColor) ? customHexColor : '#000000'"
            @input="onPickCustomColour"
          />
        </label>
        <input
          v-model="customHexColor"
          type="text"
          placeholder="#000000"
          class="h-9 w-24 rounded-md border border-border bg-surface px-2.5 font-mono text-base text-content placeholder-content-subtle outline-none focus:border-accent focus:ring-2 focus:ring-accent-subtle"
          maxlength="7"
        />
        <span
          v-if="customHexColor && !isValidHex(customHexColor)"
          class="text-xs text-danger-vivid"
        >
          {{ $t('fomatInvalid') }}
        </span>
      </div>
    </div>
    <p
      v-if="tags.length >= 5 && isInAddMode"
      class="flex items-center gap-1 text-xs text-content-muted"
    >
      <Info class="h-4 w-4 shrink-0" />
      {{ $t('tagLimitReached') }}
    </p>
    <div class="flex items-center justify-end gap-2">
      <button
        class="inline-flex h-10 cursor-pointer items-center justify-center gap-2 rounded-md bg-surface-muted px-4 py-2 text-base leading-none font-medium whitespace-nowrap text-content transition-colors focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0"
        @click="isInAddMode ? vfm.closeAll() : cancelEdit()"
      >
        {{ $t('cancel') }}
      </button>
      <button
        class="inline-flex h-10 cursor-pointer items-center justify-center gap-2 rounded-md bg-accent px-4 py-2 text-base leading-none font-medium whitespace-nowrap text-white transition-colors hover:bg-accent-hover focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0"
        :class="{ 'cursor-not-allowed': !tag || isDuplicatedTag }"
        :disabled="!tag || isDuplicatedTag"
        @click="add"
      >
        {{ $t('save') }}
      </button>
    </div>
  </vue-final-modal>
</template>
