<script setup lang="ts">
import { onLongPress } from '@vueuse/core'
import dayjs from 'dayjs'
import isYesterday from 'dayjs/plugin/isYesterday'
import localizedFormat from 'dayjs/plugin/localizedFormat'
import {
  EyeOff,
  FolderPlus,
  FolderX,
  MoreHorizontal,
  Pin,
  PinOff,
  Tag,
  Trash2,
  Volume2,
  VolumeX
} from 'lucide-vue-next'
import { computed, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import User from '../classes/user'
import { useImkitModal as useModal } from '../composables/useImkitModal'
import { SearchType } from '../enums/searchType'
import { getConfig } from '../runtime/config'
import { PORTAL_HOST_SELECTOR } from '../runtime/portalHost'
import { useImkitStore } from '../stores/imkit'
import { deriveTagPalette } from '../utils/tagColor'
import { roomTitleParts } from '../utils/roomTitle'
import Room from './../classes/room'
import Settings from './../classes/settings'
import AddToFolderModal from './AddToFolderModal.vue'
import AvatarView from './AvatarView.vue'
import DeleteRoomModal from './DeleteRoomModal.vue'
import HideRoomConfirmModal from './HideRoomConfirmModal.vue'
import HighlightedText from './HighlightedText.vue'
import MenuItemContent from './MenuItemContent.vue'
import TagsModal from './TagsModal.vue'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuPortal,
  DropdownMenuSeparator,
  DropdownMenuTrigger
} from './tribo/ui/dropdown-menu'

dayjs.extend(localizedFormat)
dayjs.extend(isYesterday)
const props = defineProps<{ source: Room }>()
const config = getConfig()
const settings = computed((): Settings => config.settings)
const styles = computed(() => config.styles)
const date = computed(() => {
  let updatedAt = dayjs(room.value?.updatedAt)
  if (updatedAt.isSame(dayjs(), 'day')) {
    return updatedAt.format('H:mm')
  } else if (updatedAt.isYesterday()) {
    return 'Yesterday'
  } else if (updatedAt.isSame(dayjs(), 'week')) {
    return updatedAt.format('dddd')
  } else if (updatedAt.isSame(dayjs(), 'year')) {
    return updatedAt.format('MMM D')
  }
  return updatedAt.format('ll')
})

const { t } = useI18n()
const imkit = useImkitStore()
const room = computed(() => {
  return imkit.rooms[props.source.id]
})
// Group rooms only — `Team-14 (3)`, direct rooms show nothing. Shared with
// ChatRoom.vue's header title via roomTitle.ts so the two can't drift. The
// count is rendered SEPARATELY from the (middle-truncated) name — see
// roomTitle.ts — so it is never clipped along with a long name.
const titleParts = computed(() => roomTitleParts(room.value))
const highlightForDisplayName = computed(() => {
  if (
    imkit.searchKeyword.length > 0 &&
    (imkit.searchType === SearchType.RoomName ||
      imkit.searchType === SearchType.RoomMember)
  ) {
    return imkit.searchKeyword
  }
  return undefined
})
const highlightForContent = computed(() => {
  if (
    imkit.searchKeyword.length > 0 &&
    (imkit.searchType === SearchType.Messages ||
      imkit.searchType === SearchType.RoomMember)
  ) {
    return imkit.searchKeyword
  }
  return undefined
})
const content = computed(() => {
  if (
    imkit.searchKeyword.length > 0 &&
    imkit.searchType === SearchType.RoomMember
  ) {
    return room.value.memberIds
      .map((id: string) => imkit.users[id])
      .filter((user: User) => user)
      .map((user: User) => user.nickname || user.id)
      .join(', ')
  }

  if (imkit.searchKeyword.length > 0 && imkit.searchType === SearchType.Files) {
    return t('foundFiles', {
      count: imkit.searchedMessageIds.get(props.source.id)?.length ?? 0
    })
  }

  return room.value.lastMessage?.previewString(room.value.isGroup)
})
const isSelected = computed(() => imkit.selectedRoomId === props.source.id)
// Deliberately NOT gated on `!isSelected`, unlike the unread badge and the
// "you were mentioned" banner below. An earlier revision did gate it, purely
// to dodge a contrast failure: the timestamp was on `text-accent`, which is a
// BACKGROUND-role token (its value is tuned so white text ON it clears 4.5:1 —
// a different constraint from the token itself being legible as text), and it
// measured 3.05:1 on `bg-accent-subtle` in blue-dark. Moving the timestamp to
// `text-accent-vivid` — the foreground half of the same split, which exists
// for exactly this role — clears 4.5:1 on all three of this row's backgrounds
// across supported palettes and colour modes, so the gate had
// nothing left to protect and was removed. An unread room should read as
// unread whether or not it happens to be the selected one.
const isUnread = computed(() => (room.value?.numberOfUnread ?? 0) > 0)
const isInFolder = computed(() => !!imkit.roomIdsInFolders[props.source.id])
const actionMenuRoomId = computed(() => imkit.actionMenuRoomId)
const searchKeyword = computed(() => imkit.searchKeyword)
const isSticky = computed(() => room.value.pref?.sticky ?? false)
const isHidden = computed(() => room.value.pref?.hidden ?? false)
const sortedFolderIds = computed(() => imkit.sortedFolderIds)
const showTagsModal = () => {
  const { open } = useModal({
    component: TagsModal,
    attrs: {
      roomId: props.source.id
    }
  })
  open()
}
const menuOpen = computed({
  get: () => actionMenuRoomId.value === props.source.id,
  set: (value: boolean) => {
    imkit.$patch({ actionMenuRoomId: value ? props.source.id : '' })
  }
})
const selectRoom = async () => {
  // Only the ROOM action menu can suppress selection now. The folder menu
  // that set actionMenuFolderId was removed with f7632d6 — management moved
  // into the manage-folders dialog — so that half of the guard could only
  // ever read '' and was dead.
  if (actionMenuRoomId.value) {
    return
  }
  imkit.$patch({
    selectedRoomId: props.source.id,
    actionMenuRoomId: ''
  })
  const isSearchInRoomMode = !!imkit.searchKeyword
  imkit.$patch({
    messageSearchKeyword: isSearchInRoomMode ? imkit.searchKeyword : '',
    isSearchInRoomMode
  })
}
const toggleSticky = async () => {
  await imkit.updateRoomPrefs({
    roomId: props.source.id,
    prefs: {
      sticky: !isSticky.value
    }
  })
}
const toggleHidden = async () => {
  // Un-hiding is the recovery path for a mistaken hide, so it must NOT
  // prompt — a dialog in front of it would make the mistake harder to undo
  // than to make. Only the hide direction (removing the room from the list)
  // is confirmed, via the shared destructive-confirmation shell.
  if (isHidden.value) {
    await imkit.updateRoomPrefs({
      roomId: props.source.id,
      prefs: {
        hidden: false
      }
    })
    return
  }
  const { open } = useModal({
    component: HideRoomConfirmModal,
    attrs: {
      roomId: props.source.id
    }
  })
  open()
}
const toggleDelete = async () => {
  const { open } = useModal({
    component: DeleteRoomModal,
    attrs: {
      roomId: props.source.id
    }
  })
  open()
}
const removeRoomFromFolder = async () => {
  await imkit.removeRoomFromFolder(props.source.id)
}
const addToFolder = async () => {
  const { open } = useModal({
    component: AddToFolderModal,
    attrs: {
      roomId: props.source.id
    }
  })
  open()
}
const roomCellRef = ref<HTMLElement | null>(null)

const onLongPressCallbackHook = () => {
  menuOpen.value = !menuOpen.value
}

onLongPress(roomCellRef, onLongPressCallbackHook, {
  modifiers: { prevent: true }
})
const roomsInSelectedFolder = computed(() => {
  return imkit.roomsInSelectedFolder
})
// Mirrors TagsModal.vue's own hardcoded cap (`tags.length >= 5`) — there is
// no shared constant to import, so this is the same magic number, kept in
// sync deliberately rather than introducing a new source of truth.
const MAX_TAGS = 5
const tagCount = computed(() => room.value?.pref?.tags?.length ?? 0)
// Right-click opens the same menu as the hover trigger, per the design
// reference. The trigger element stays in the DOM (just visually hidden via
// `hidden`/`group-hover:flex`) so radix still has an anchor to position the
// content against once `menuOpen` forces it visible.
const onRowContextMenu = () => {
  menuOpen.value = true
}
// Chip fill/label, derived per theme from the single stored hex — the same
// helper and the same `.tag-chip` rule (src/style.css) TagsModal.vue uses,
// so the list chip and the dialog chip cannot disagree.
const tagChipStyle = (tagHex: string) => {
  const palette = deriveTagPalette(tagHex)
  return {
    '--tag-bg': palette.lightBg,
    '--tag-fg': palette.lightFg,
    '--tag-bg-dark': palette.darkBg,
    '--tag-fg-dark': palette.darkFg
  }
}
</script>

<template>
  <!--
    Full-bleed row: no horizontal gutter and no corner radius, so the row's
    fill (hover, selected) spans the whole list column edge to edge. Rows are
    separated only by their own internal spacing — no divider line between
    them — per the design reference.
  -->
  <div v-if="room" class="relative flex items-center justify-center gap-1.5">
    <div
      v-if="isInFolder && !searchKeyword"
      data-testid="folder-rail"
      class="pointer-events-none absolute inset-y-0 left-4 z-10 w-0.5 shrink-0 bg-accent-vivid opacity-40"
      :class="{
        'rounded-t-full': roomsInSelectedFolder[0]?.id === props.source.id,
        'rounded-b-full':
          roomsInSelectedFolder[roomsInSelectedFolder.length - 1]?.id ===
          props.source.id
      }"
    />
    <!--
      Room-row floor is 68px, reached by VERTICAL PADDING: `py-2.5` (10px)
      rather than `py-2` (8px). The row's height is set by its 50px avatar
      plus that padding, so 8px gave 66px and 10px gives 70px. `min-h-[68px]`
      records the contractual floor but is not what binds — the avatar and
      padding are — which is exactly why RoomList's virtualiser estimate is
      70 and not 68: the RENDERED PITCH, measured top-to-top in
      tests/e2e/messenger-redesign.spec.ts, is 70px. Do not "correct" that
      estimate to match this min-height; an 8px error survived in this file
      once by assuming the two are the same number.

      `items-center` keeps the 50px avatar centred as the padding grows, so
      the extra height distributes evenly above and below rather than
      pushing content off-centre.
    -->
    <div
      ref="roomCellRef"
      data-testid="room-cell"
      :data-room-id="room.id"
      :data-selected="isSelected"
      class="group relative flex min-h-[68px] grow cursor-pointer items-center gap-3 px-4 py-2.5 select-none sm:hover:bg-surface-hover"
      :class="{
        'bg-accent-subtle': isSelected,
        'ml-4': isInFolder && !searchKeyword
      }"
      @click="selectRoom"
      @contextmenu.prevent="onRowContextMenu"
    >
      <div
        class="relative h-[50px]! w-[50px]! shrink-0"
        :data-selected="isSelected"
      >
        <!--
          A GROUP renders as ONE avatar carrying a message glyph — not the
          stacked pair of member photos this used to draw. That stacked pair
          was the only thing in the room list that ever overlapped two
          circles, so the whole separator-ring apparatus that went with it
          (`border-2 border-surface`, `group-hover:border-surface-muted` and
          a selected-state `border-accent-subtle`) is DELETED here rather
          than left dormant.

          That ring was also the stray-outline bug on the selected row: it
          appended `border-accent-subtle` while `border-surface` stayed on
          the element unconditionally, and since both are plain (non-hover)
          border-colour utilities of equal specificity, the winner was
          decided by stylesheet order — Tailwind emits `.border-surface`
          AFTER `.border-accent-subtle` — so a selected row kept painting
          the ring in the UNSELECTED backdrop colour over its now-selected
          `bg-accent-subtle` fill. Removing the ring removes the bug and the
          bug's whole mechanism.

          Avatars carry no border or ring anywhere in this component now.
        -->
        <!--
          A group shows its COVER when one is set, and the UsersRound glyph
          only as the fallback. This used to be two branches with the group
          one hard-coding `url=""`, which made `Room.avatars`' cover branch
          dead for groups — a room could set a cover and see it nowhere.

          `coverUrl`, not `avatars[0].url`: for a group with no cover,
          `avatars` falls through to the MEMBER list, so `avatars[0]` is some
          member's photo standing in as the group's. That is what the
          hard-coded empty string was avoiding, and it is why this cannot
          simply reuse the non-group expression.
        -->
        <avatar-view
          :url="room.isGroup ? room.coverUrl : room.avatars[0].url"
          :name="room.isGroup ? (room.displayName ?? '') : room.avatars[0].name"
          :is-group="room.isGroup"
          class="relative"
        />
        <!--
          The pinned badge was `bg-surface-muted` with a `text-content-muted`
          Pin. Both halves are tokens, so this was not the half-migration bug
          this file has shipped before — the icon/badge pair measures 6.75:1 to
          10.41:1 across the four blocks, comfortably clear.

          The failing pair is the badge against the ROW behind it, and it fails
          by construction rather than by a narrow margin: the row's hover state
          is `sm:hover:bg-surface-hover`, the exact token the badge was filled
          with. Hovering a pinned room painted the badge the same colour as its
          own backdrop — 1.00:1, the badge simply disappears. At rest it was
          only slightly better, since `surface-muted` against the list column's
          `panel` is a very small step (the same faintness recorded for the
          panel/surface pair in CLAUDE.md).

          `bg-accent` with a white glyph is the fix: accent is the background
          role, and both floors it needs are already asserted in
          tests/tokenContrast.test.ts — white-on-accent >= 4.5:1, and accent
          against surface / panel / surface-muted >= 3:1. So the badge is
          guaranteed to separate from the row in every state including hover,
          and a drift in either direction fails the suite instead of shipping.

          ROUND 4: that fix left one pair unchecked — a GROUP avatar
          (AvatarView.vue) is ALSO `bg-accent`, and the badge sits directly
          on top of it (`-right-1 -bottom-1` overlaps the avatar circle), so
          at rest and when selected the badge fill and the avatar fill are
          the identical token and the badge merges into it (1:1).

          No existing background-role token (the only kind allowed to carry
          a plain white glyph in every supported palette and colour mode, per the accent/danger
          split documented in src/style.css) separates from `accent` in every
          block: `content` reads 3.64/4.03/1.19/3.89 against accent across
          blue-light/blue-dark/neutral-light/neutral-dark — the neutral-light
          avatar (#2b2b2b, near-black) sits almost on top of `content`
          (#1d1d1d) there — and `content` also isn't theme-stable as a FILL
          (it flips from near-black to near-white with the theme, which would
          make the white Pin glyph disappear in dark mode; `content-inverse`
          doesn't exist, per CLAUDE.md). `danger` fails even more directly:
          1.01:1 against blue's own accent, since the two happen to sit at
          nearly the same lightness in that preset.

          So the fill stays `bg-accent` (already proven against the row) and
          a `ring-2 ring-panel` is added purely to separate the badge from
          the AVATAR underneath — a fixed-colour outline "punches a hole"
          between two adjacent same-colour fills regardless of whether the
          fill and the ring surface itself would clear 3:1 against each
          other. `panel` against `accent` measures 4.61:1 (blue light) /
          3.83:1 (blue dark) / 14.16:1 (neutral light — the case this exists
          for) / 4.07:1 (neutral dark), i.e. clears 3:1 in all four with the
          worst margin still 0.83. Against the row backgrounds the ring
          mostly disappears (panel-on-panel at rest is ~1:1) — that is fine,
          the FILL already carries that separation; the ring's only job is
          the avatar boundary. tests/pinnedBadgeSeparation.test.ts asserts
          the ring is present and that its token is not `accent` (so it
          cannot silently re-collide with the fill it is meant to separate
          from).
        -->
        <div
          v-if="isSticky"
          class="absolute -right-1 -bottom-1 flex h-5 w-5 items-center justify-center rounded-lg bg-accent p-[3px] ring-2 ring-panel"
        >
          <Pin class="h-3 w-3 text-white" />
        </div>
      </div>
      <!--
        ROUND 14: `pr-7` used to sit here, on the whole column, which pushed
        every timestamp on the name/date line 28px inward to protect a line
        it never actually needed to protect — see the comment on the
        content/member-search line below for where the gutter actually
        belongs and why.

        This line does not need a gutter of its own. The `...` trigger stays
        anchored to the OUTER row (`right-4`, vertically centred on the full
        row height — see its own comment further down for why it was
        deliberately NOT moved into this slot), so on a short row it can be
        vertically level with the timestamp. What keeps it from painting over
        the timestamp is not spacing but the timestamp's own
        `sm:group-hover:invisible` a few lines down: the instant the row is
        hovered (desktop only) and the trigger becomes visible, the timestamp
        vacates — same box, `invisible` not `hidden`, so the row doesn't
        reflow — leaving nothing there for the trigger to occlude. That
        mechanism already existed before this round; it was just never
        exercised to justify dropping the gutter until now.
      -->
      <div class="flex w-0 min-w-0 grow flex-col text-left">
        <div class="flex justify-between gap-2">
          <div class="flex min-w-0 flex-1 items-center gap-1 overflow-hidden">
            <!--
              This element carries the UNREAD signal (weight) and nothing
              else. Selection is drawn by the row's `accent-subtle` FILL, not
              here — neither of the two channels available on a label can
              express it. Colour cannot: with an achromatic `brand` seed,
              `accent-vivid` is grey, so a selected name can have lower contrast than
              its neighbours and reads as disabled rather than selected.
              Weight cannot: it is already spoken for below, and reusing it
              would make a selected-and-read row identical to an
              unselected-and-unread one. See the note beside
              `--color-accent-subtle` in src/style.css for the full chain.

              NOTE: selection used to ALSO draw an inset `ring-accent`, which
              was removed when the rows went full-bleed (fill-only selection,
              per the design reference). That makes the fill the sole
              selection channel, and `accent-subtle` vs the `surface-muted`
              hover fill measures ΔE76 1.26 / 1.96 / 0.35 / 0.96 across
              blue-light / blue-dark / neutral-light / neutral-dark — all
              under the ~2.3 JND, so a hovered row is not reliably
              distinguishable from the selected one on a hover-capable
              desktop viewport. This is a known, accepted trade-off, not an
              oversight; hover is gated to `sm:` + `(hover:hover)`, so touch
              and narrow viewports are unaffected.

              This element deliberately does NOT carry `flex-1` any more —
              that made it fill the whole meta column regardless of how
              short the name was, shoving the mute icon and the `(n)` count
              all the way to the far right, flush against the timestamp
              column instead of sitting ~4px after the name. Sized to
              content + `min-w-0` instead, so it only takes the room it
              needs and shrinks when the name is long enough to need the
              space back.

              The `(n)` count is a SEPARATE, `shrink-0` sibling
              (`room-name-count` below) rather than baked into this string —
              round 12: a trailing `(n)` used to be lost whenever the name
              itself was long enough to end-truncate. The name here is now
              middle-truncated in JS (`roomTitleParts` /
              `middleTruncateByDisplayWidth`) rather than relying on CSS
              `text-ellipsis` to cut the end; `text-ellipsis` stays only as
              a defensive fallback for the (should-not-happen) case where
              the truncated string still overflows.
            -->
            <div
              data-testid="room-name"
              class="min-w-0 overflow-hidden text-base text-ellipsis whitespace-nowrap text-content"
              :class="isUnread ? 'font-extrabold' : 'font-semibold'"
            >
              <highlighted-text
                :text="titleParts.truncatedName"
                :highlight="highlightForDisplayName"
              />
            </div>
            <div
              v-if="titleParts.countSuffix"
              data-testid="room-name-count"
              class="shrink-0 text-base text-content"
              :class="isUnread ? 'font-extrabold' : 'font-semibold'"
            >
              {{ titleParts.countSuffix }}
            </div>
            <VolumeX
              v-if="room.muted"
              data-testid="room-mute-icon"
              class="h-3.5 w-3.5 shrink-0 text-content-muted"
            />
          </div>
          <!--
            The timestamp and the `...` trigger occupy the same meta slot:
            the trigger is a BARE button (no border/background/shadow, per
            the design reference) that replaces the timestamp on hover,
            rather than floating a separate chip over the row. `invisible`
            (not `hidden`) on the timestamp keeps its box in flow so the
            column doesn't reflow when the trigger swaps in.

            The trigger and its DropdownMenu are nested here, positioned
            against this slot — see the comment beside them below.
          -->
          <div class="relative flex-none">
            <div
              class="text-xs whitespace-nowrap"
              :class="[
                isUnread ? 'text-accent-vivid' : 'text-content-subtle',
                { 'sm:group-hover:invisible': true, invisible: menuOpen }
              ]"
            >
              {{ date }}
            </div>
            <!--
            The trigger lives in the META SLOT (beside the timestamp), not on the
            outer row. It used to be anchored to the row with
            `top-1/2 -translate-y-1/2`, centring it against the 50px avatar, which
            is why BOTH the timestamp and the unread badge had to vacate on hover:
            row-centred, the dots land between the two lines and would paint over
            whichever one is there.

            Keeping the unread badge visible while hovering (2026-08-20, at the
            user's request) makes that untenable — the badge is the thing a hover
            must not hide. So the dots move back onto the timestamp's line and
            swap with the timestamp alone; the badge on the line below is now
            never occluded and keeps its `sm:group-hover` visibility.

            Positioned against the meta slot rather than the row because the row
            is `items-center`: when the text column is shorter than the avatar it
            gets centred, so the first line's offset from the row's top is not a
            constant and no fixed `top-*` could track it.
          -->
            <DropdownMenu v-model:open="menuOpen">
              <DropdownMenuTrigger as-child>
                <button
                  type="button"
                  data-testid="room-menu-trigger"
                  class="absolute top-1/2 right-0 hidden -translate-y-1/2 cursor-pointer items-center justify-center text-content-muted sm:group-hover:flex"
                  :class="{ 'flex!': menuOpen }"
                >
                  <MoreHorizontal class="h-5 w-5" />
                </button>
              </DropdownMenuTrigger>
              <DropdownMenuPortal :to="PORTAL_HOST_SELECTOR">
                <DropdownMenuContent
                  data-testid="room-action-menu"
                  align="end"
                  side="bottom"
                  :side-offset="8"
                >
                  <!--
                  Structurally the same "separator between two non-empty groups"
                  rule the message menu now enforces
                  (useMessageActionItems.ts's `flattenMenuGroups`) applies here
                  too, but this row's primary group can never actually empty
                  out: pin/mute/tag/hide render unconditionally, and only the
                  folder item (removeFromFolder / addToFolder) is conditional,
                  with the other three items always present alongside it. So a
                  single separator directly ahead of the always-present delete
                  item is already safe — there is no permission permutation
                  that leaves it first, last, or beside another.
                -->
                  <DropdownMenuItem @select="toggleSticky">
                    <MenuItemContent
                      :icon="isSticky ? PinOff : Pin"
                      :label="isSticky ? $t('unpin') : $t('pin')"
                    />
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    @select="imkit.toggleNotification(props.source.id)"
                  >
                    <MenuItemContent
                      :icon="room.muted ? Volume2 : VolumeX"
                      :label="room.muted ? $t('unmute') : $t('mute')"
                    />
                  </DropdownMenuItem>
                  <DropdownMenuItem @select="showTagsModal">
                    <MenuItemContent :icon="Tag" :label="$t('tag')" />
                    <span class="ml-auto text-xs text-content-muted"
                      >{{ tagCount }}/{{ MAX_TAGS }}</span
                    >
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    v-if="isInFolder"
                    @select="removeRoomFromFolder"
                  >
                    <MenuItemContent
                      :icon="FolderX"
                      :label="$t('removeFromFolder')"
                    />
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    v-else-if="sortedFolderIds.length > 0"
                    @select="addToFolder"
                  >
                    <MenuItemContent
                      :icon="FolderPlus"
                      :label="$t('addToFolder')"
                    />
                  </DropdownMenuItem>
                  <DropdownMenuItem @select="toggleHidden">
                    <MenuItemContent
                      :icon="EyeOff"
                      :label="isHidden ? $t('unhide') : $t('hide')"
                    />
                  </DropdownMenuItem>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem
                    class="text-danger-vivid focus:text-danger-vivid"
                    @select="toggleDelete"
                  >
                    <!-- danger-vivid, NOT content-muted like the icons above. The
                       colour the item sets on its container does not reach the
                       glyph, because the glyph carries its own colour class and a
                       child's own declaration beats an inherited one. Muting it
                       left a red label beside a grey trash can. -->
                    <MenuItemContent
                      :icon="Trash2"
                      :label="$t('delete')"
                      :danger="true"
                    />
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenuPortal>
            </DropdownMenu>
          </div>
        </div>
        <!--
          This line carried a permanent `pr-7` gutter and the badge carried
          `sm:group-hover:invisible`. Both existed for one reason: the `...`
          trigger was centred on the OUTER row, so it landed over THIS line
          and everything on it had to either reserve space or vacate.

          2026-08-20: the trigger moved onto the timestamp's line (see its
          comment above), so nothing on this line is ever occluded. The
          gutter and the badge's hover-vacate are both gone with it — the
          badge now stays put while the row is hovered, which is the point
          of the change, and the preview text gets back the 28px it was
          permanently truncating early to protect a collision that can no
          longer happen.
        -->
        <div
          v-if="settings.enableReadReceipt"
          class="flex items-center justify-between gap-2"
        >
          <div
            class="truncate text-base"
            :class="
              isUnread ? 'font-semibold text-content' : 'text-content-subtle'
            "
          >
            <highlighted-text
              :text="content ?? ''"
              :highlight="highlightForContent"
            />
          </div>
          <div
            v-if="room.numberOfUnread > 0 && !isSelected"
            data-testid="room-unread-badge"
            class="flex h-5 min-w-5 shrink-0 items-center justify-center rounded-full bg-accent px-1.5 text-center text-xs leading-none font-semibold text-white"
            :style="styles.roomListUnreadBadge"
          >
            {{ room.numberOfUnread > 99 ? '99+' : room.numberOfUnread }}
          </div>
        </div>
        <div
          v-if="room.isMentioned && room.numberOfUnread > 0 && !isSelected"
          class="text-xs text-accent-vivid"
        >
          {{ $t('youWereMentioned') }}
        </div>
        <div v-if="room.pref?.tags" class="mt-1 flex flex-wrap gap-1">
          <div
            v-for="tag in room.pref?.tags ?? []"
            :key="tag"
            class="tag-chip overflow-hidden rounded-full px-3 py-1 text-xs font-semibold text-ellipsis whitespace-nowrap"
            :style="tagChipStyle((room.pref?.tagColors || {})[tag])"
          >
            {{ tag }}
          </div>
        </div>
        <div
          v-if="searchKeyword && imkit.searchType === SearchType.Messages"
          class="text-content-subtle"
        >
          {{
            $t('foundMessages', [
              imkit.searchedMessageIds.get(source.id)?.length ?? 0
            ])
          }}
        </div>
      </div>
    </div>
  </div>
</template>

