<script setup lang="ts">
import { computed } from 'vue'
import actionHandler from './../../../utils/line-action-handler'
/* eslint-disable @typescript-eslint/no-explicit-any */
const props = withDefaults(
  defineProps<{ content: any; roomId?: string; depth?: number }>(),
  {
    roomId: '',
    depth: 0
  }
)
/* eslint-enable @typescript-eslint/no-explicit-any */
/*
 * These are FALLBACKS ONLY. A flex message that names its own `color` still
 * gets exactly that colour — the sender's choice is never overridden. What
 * changed is what we paint when the message names nothing.
 *
 * The four literals these replace were LINE's spec defaults, and each was a
 * colour that belonged to no palette in this app: `#17c950` is a green some
 * way off PinChat's `#02b13f`, so two greens sat side by side in one bubble,
 * and `#dcdfe5` + `#000000` is a fixed-light pair that stayed fixed-light in
 * dark mode. Each maps onto the role token that already does this exact job
 * and is already held to 4.5:1 by the derivation: `accent` is defined as the
 * background that carries white text, `accent-vivid` as the link/foreground
 * role, `surface-muted` + `content` as a checked neutral pair.
 *
 * White stays a literal on the primary button: white is white in both colour
 * modes, so it needs no token.
 */
const color = computed(() => {
  if (props.content.style === 'primary') {
    return '#ffffff'
  }
  if (props.content.style === 'secondary') {
    return 'var(--color-content)'
  }
  return props.content.color || 'var(--color-accent-vivid)'
})
const backgroundColor = computed(() => {
  if (props.content.style === 'primary') {
    return props.content.color || 'var(--color-accent)'
  }
  if (props.content.style === 'secondary') {
    return props.content.color || 'var(--color-surface-muted)'
  }
  return ''
})
const handleClick = () => {
  if (props.roomId && props.content.action) {
    actionHandler(props.roomId, props.content.action)
  }
}
</script>

<template>
  <button
    :class="[content.size === 'md' ? 'h-[52px]' : 'h-10']"
    class="rounded-lg"
    :style="{
      color: color,
      backgroundColor: backgroundColor
    }"
    @click="handleClick"
  >
    {{ content.action?.label ?? '' }}
  </button>
</template>

<style scoped></style>
