import QuickLRU from 'quick-lru'
import { shallowRef } from 'vue'

export const imageCache = new QuickLRU<string, string>({ maxSize: 500 })
export const translationCache = new QuickLRU<string, string>({ maxSize: 500 })
export const roomTagCache = new QuickLRU<string, string[]>({ maxSize: 500 })

// Preserve Set replacement semantics so existing Vue consumers still rerender.
export const imageFailuresRef = shallowRef<Set<string>>(new Set())

export const addImageFailure = (url: string): void => {
  if (imageFailuresRef.value.has(url)) return
  imageFailuresRef.value = new Set([...imageFailuresRef.value, url])
}

export const removeImageFailure = (url: string): void => {
  if (!imageFailuresRef.value.has(url)) return
  const next = new Set(imageFailuresRef.value)
  next.delete(url)
  imageFailuresRef.value = next
}

export const clearImageCacheState = (): void => {
  imageCache.clear()
  imageFailuresRef.value = new Set()
}
