<script setup lang="ts">
import { computed } from 'vue'
import { TemplateMessage } from './../../classes/message'
import actionHandler from './../../utils/line-action-handler'
const props = defineProps<{ message: TemplateMessage }>()
const isIncoming = computed(() => props.message.isIncoming)
</script>

<template>
  <!-- Self-contained plate. This component previously had NO background of
       its own and relied on MessageCell's `bg-white! dark:bg-zinc-800!`
       wrapper; when that wrapper went transparent, the card rendered as
       borderless floating text on the canvas, so it delimits itself now rather
       than depending on an ancestor.

       It takes the BUBBLE pair for its direction, matching the flex cards and
       the text bubble beside it. An earlier round removed direction tinting
       here entirely, reacting to an outgoing branch that painted raw
       `text-gray-100` / `text-slate-100` — near-whites measuring ~1.02:1 on
       the light plate of the day. That diagnosis was right about the RAW
       classes and wrong about the tinting: dropping it left a sent template
       card flat beside a sent text bubble that is tinted. Every value here is
       a token the derivation checks against the fill under it. -->
  <div
    class="w-[250px] cursor-pointer overflow-hidden rounded-lg text-base"
    :class="
      isIncoming
        ? 'bg-message text-content'
        : 'bg-message-own text-message-own-content'
    "
  >
    <img
      v-if="message.template.thumbnailImageUrl"
      class="object-cover text-content"
      :class="{
        'object-contain': message.template.imageSize === 'contain'
      }"
      :style="{
        'background-color':
          message.template.imageBackgroundColor ?? 'var(--color-surface-muted)',
        height: `${
          message.template.imageAspectRatio === 'square' ? 250 : 250 / 1.51
        }px`
      }"
      :src="message.template.thumbnailImageUrl"
      @click="actionHandler(message.roomId, message.template.defaultAction)"
    />
    <div
      data-testid="template-message-body"
      class="flex flex-col gap-1 px-4 py-2.5"
      @click="actionHandler(message.roomId, message.template.defaultAction)"
    >
      <div>{{ message.template.title?.substring(0, 40) }}</div>
      <div
        v-if="message.template.text"
        class="text-base"
        :class="isIncoming ? 'text-content-subtle' : 'text-message-own-content'"
      >
        {{
          !message.template.thumbnailImageUrl && !message.template.title
            ? message.template.text.substring(0, 160)
            : message.template.text.substring(0, 60)
        }}
      </div>
    </div>
    <div
      v-if="(message.template.actions?.length ?? 0) > 0"
      class="flex flex-col gap-2 border-t py-3"
      :class="isIncoming ? 'border-content/8' : 'border-message-own-content/14'"
    >
      <div
        v-for="action in message.template.actions ?? []"
        :key="action.label"
        class="flex items-center justify-center p-0.5 text-base"
        :class="isIncoming ? 'text-content-muted' : 'text-message-own-content'"
        @click="actionHandler(message.roomId, action)"
      >
        {{ action.label }}
      </div>
    </div>
  </div>
</template>

<style scoped></style>
