import { computed, ref } from 'vue'
import type ChatRoomContent from '../classes/chatRoomContent'
import { useImkitStore } from '../stores/imkit'
import { sortChatRoomContentMedia } from '../utils/chatRoomContent'

export function useRoomContentMediaNavigation(
  getRoomId: () => string | undefined
) {
  const imkit = useImkitStore()
  const selectedMediaId = ref<string | null>(null)
  let selectionGeneration = 0
  let previousNavigationRequest: {
    key: string
    promise: Promise<void>
  } | null = null

  const orderedMedia = computed(() => {
    const roomId = getRoomId()
    if (!roomId || imkit.chatRoomContentMediaRoomId !== roomId) return []
    return sortChatRoomContentMedia(imkit.chatRoomContentMedia)
  })
  // The API and gallery are newest-first. In the lightbox, left/previous moves
  // toward older media (+1), while right/next moves toward newer media (-1).
  const selectedMediaIndex = computed(() =>
    orderedMedia.value.findIndex((item) => item._id === selectedMediaId.value)
  )
  const selectedMedia = computed(
    () => orderedMedia.value[selectedMediaIndex.value] ?? null
  )
  const mediaCount = computed(() => {
    const roomId = getRoomId()
    if (!roomId || imkit.chatRoomContentMediaRoomId !== roomId) {
      return orderedMedia.value.length
    }
    return Math.max(
      orderedMedia.value.length,
      imkit.chatRoomContentMediaTotalCount
    )
  })
  const canNavigatePrevious = computed(() => {
    const roomId = getRoomId()
    const index = selectedMediaIndex.value
    if (index < 0) return false
    if (index < orderedMedia.value.length - 1) return true
    return (
      Boolean(roomId) &&
      imkit.chatRoomContentMediaRoomId === roomId &&
      imkit.chatRoomContentMediaHasMore
    )
  })
  const canNavigateNext = computed(() => selectedMediaIndex.value > 0)

  const selectMedia = (media: ChatRoomContent | null) => {
    selectionGeneration += 1
    selectedMediaId.value = media?._id ?? null
  }

  const navigatePrevious = async () => {
    const roomId = getRoomId()
    const index = selectedMediaIndex.value
    if (!roomId || index < 0) return

    const older = orderedMedia.value[index + 1]
    if (older) {
      selectMedia(older)
      return
    }
    if (
      imkit.chatRoomContentMediaRoomId !== roomId ||
      !imkit.chatRoomContentMediaHasMore
    ) {
      return
    }

    const currentId = selectedMediaId.value
    const currentGeneration = selectionGeneration
    const currentSessionEpoch = imkit.sessionEpoch
    await imkit.fetchRoomContentMedia({ roomId, loadMore: true })
    if (
      !currentId ||
      getRoomId() !== roomId ||
      selectedMediaId.value !== currentId ||
      selectionGeneration !== currentGeneration ||
      imkit.sessionEpoch !== currentSessionEpoch
    ) {
      return
    }

    const currentIndex = orderedMedia.value.findIndex(
      (item) => item._id === currentId
    )
    if (currentIndex < 0) return
    const loadedOlder = orderedMedia.value[currentIndex + 1]
    if (loadedOlder) selectMedia(loadedOlder)
  }

  const previousMedia = () => {
    const key = `${getRoomId() ?? ''}:${selectionGeneration}`
    if (previousNavigationRequest?.key === key) {
      return previousNavigationRequest.promise
    }

    const request = {
      key,
      promise: Promise.resolve()
    }
    request.promise = navigatePrevious().finally(() => {
      if (previousNavigationRequest === request) {
        previousNavigationRequest = null
      }
    })
    previousNavigationRequest = request
    return request.promise
  }

  const nextMedia = async () => {
    const index = selectedMediaIndex.value
    if (index <= 0) return
    selectMedia(orderedMedia.value[index - 1])
  }

  return {
    orderedMedia,
    selectedMedia,
    selectedMediaIndex,
    mediaCount,
    canNavigatePrevious,
    canNavigateNext,
    selectMedia,
    previousMedia,
    nextMedia
  }
}
