<script setup lang="ts">
import { ref } from 'vue'
import { useVfm } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

const vfm = useVfm()
const imkit = useImkitStore()
const isLoading = ref(false)

const props = defineProps<{
  messageId: string
  roomId: string
}>()

const cancel = () => vfm.closeAll()

const confirm = async () => {
  isLoading.value = true
  try {
    await imkit.recallMessage({
      _id: props.messageId,
      roomId: props.roomId
    })
    vfm.closeAll()
  } catch (error) {
    console.error('Error unsending message:', error)
  } finally {
    isLoading.value = false
  }
}
</script>

<template>
  <ConfirmDialogShell
    :title="$t('unsendMessageConfirmTitle')"
    :cancel-label="$t('cancel')"
    :confirm-label="$t('unsendMessageAction')"
    confirm-test-id="unsend-message-confirm-action"
    :loading="isLoading"
    @cancel="cancel"
    @confirm="confirm()"
  >
    {{ $t('unsendMessageConfirmDescription') }}
  </ConfirmDialogShell>
</template>
