<script setup lang="ts">
import { computed } from 'vue'
import FlexMessageComponent from '../components/FlexMessageComponent.vue'
/* eslint-disable @typescript-eslint/no-explicit-any */
const props = withDefaults(
  defineProps<{ content: any; roomId?: string; isIncoming?: boolean }>(),
  { roomId: '', isIncoming: true }
)
/* eslint-enable @typescript-eslint/no-explicit-any */
const header = computed(() => props.content.header)
const hero = computed(() => props.content.hero)
const body = computed(() => props.content.body)
const footer = computed(() => props.content.footer)
const headerStyle = computed(() => props.content.styles?.header)
const heroStyle = computed(() => props.content.styles?.hero)
const bodyStyle = computed(() => props.content.styles?.body)
const footerStyle = computed(() => props.content.styles?.footer)
const bodyPadding = computed(() => {
  switch (props.content.size) {
    case 'nano':
      return '10px'
    case 'micro':
      return '13px'
    case 'kilo':
      return footer.value ? '13px 13px 17px 13px' : '13px'
    case 'mega':
      return footer.value ? '19px 20px 10px 20px' : '20px'
    case 'giga':
      return footer.value ? '19px 20px 10px 20px' : '20px'
    default:
      return '20px'
  }
})
</script>

<template>
  <!--
    The card follows the message bubbles either side of it: a received flex
    message uses the received pair, a sent one the sent pair. It was a fixed
    `bg-surface-muted` with a hardcoded `text-[#444444]` foreground — a token
    plate carrying raw text, so in dark mode it put dark grey on dark grey. It
    is the wrapper for every flex message, so one line had wide blast radius.
  -->
  <div
    class="overflow-hidden"
    :class="{
      'bg-message text-content': isIncoming,
      'bg-message-own text-message-own-content': !isIncoming,
      'w-[120px]': content.size === 'nano',
      'w-[160px]': content.size === 'micro',
      'w-[260px]': content.size === 'kilo',
      'w-[300px]': content.size === 'mega' || !content.size,
      'w-[386px]': content.size === 'giga'
    }"
  >
    <flex-message-component
      v-if="header"
      :content="header"
      :room-id="roomId"
      :style="{
        backgroundColor: headerStyle?.backgroundColor,
        borderBottom: headerStyle?.separator
          ? `1px solid ${headerStyle?.separatorColor}`
          : 'none'
      }"
    />
    <flex-message-component
      v-if="hero"
      :content="hero"
      :room-id="roomId"
      :style="{
        backgroundColor: heroStyle?.backgroundColor,
        borderBottom: heroStyle?.separator
          ? `1px solid ${heroStyle?.separatorColor}`
          : 'none'
      }"
    />
    <flex-message-component
      v-if="body"
      :content="body"
      :room-id="roomId"
      :style="{
        backgroundColor: bodyStyle?.backgroundColor,
        borderBottom: bodyStyle?.separator
          ? `1px solid ${bodyStyle?.separatorColor}`
          : 'none',
        padding: bodyPadding
      }"
    />
    <flex-message-component
      v-if="footer"
      :content="footer"
      :room-id="roomId"
      class="p-2.5"
      :style="{
        backgroundColor: footerStyle?.backgroundColor,
        borderBottom: footerStyle?.separator
          ? `1px solid ${footerStyle?.separatorColor}`
          : 'none'
      }"
    />
  </div>
</template>

<style scoped></style>
