<script setup lang="ts">
import axiosModule, { AxiosProgressEvent } from 'axios'
import { AlertTriangle, Download } from 'lucide-vue-next'
import { computed, onUnmounted, ref } from 'vue'
import RadialProgress from 'vue3-radial-progress'
import { useImkitStore } from '../stores/imkit'
import { FileMessage, MessageStatus } from './../classes/message'
import { getAxios } from './../runtime/axios'
import { escapeHtml } from './../utils/escapeHtml'
import { getFileIcon } from './../utils/fileIcon'
import { joinFileName } from './../utils/fileName'
import { formatBytes } from './../utils/formatBytes'
import { highlightHtmlText } from './../utils/highlightHtmlText'
import { isApiOrigin } from './../utils/isApiOrigin'

const imkit = useImkitStore()
const props = defineProps<{ message: FileMessage }>()
const isIncoming = computed(() => props.message.isIncoming)
const uploadProgresses = computed(() => imkit.uploadProgresses)
const downloadProgresses = computed(() => imkit.downloadProgresses)
const fileIcon = computed(() => getFileIcon(props.message.fileExtension))

const downloadPercent = computed(() =>
  Math.round((downloadProgresses.value[props.message.url] ?? 0) * 100)
)

// Deliberately NOT a computed, and `message.url` is deliberately read
// inline in the template instead. A `Message` is a plain class instance
// living in the store's linked list, not a reactive proxy, so a computed
// over `message.url` registers NO reactive dependency: it evaluates once
// and caches that answer forever. The ring would then never appear when a
// send starts, nor clear when the server hands back a URL — it would only
// ever reflect whatever the url happened to be at first render. Verified in
// the browser: with the value patched to '', a forced re-render still read
// the stale cached result. A template expression is re-evaluated on every
// render, so it always sees the current url. `message.url !== ''` on the
// download button below relies on exactly the same property.
//
// Only the percentage is a computed, because `uploadProgresses` really is
// reactive store state.
const uploadPercent = computed(() =>
  Math.round((uploadProgresses.value[props.message.id] ?? 0) * 100)
)

const fileSize = computed(() => formatBytes(props.message.bytes))

type DownloadState = 'idle' | 'downloading' | 'error'
const downloadState = ref<DownloadState>('idle')
let errorTimer: ReturnType<typeof setTimeout> | null = null
let isUnmounted = false

const download = async () => {
  if (downloadState.value !== 'idle') return
  downloadState.value = 'downloading'
  try {
    const { url, fileName, fileExtension } = props.message
    // The authenticated client (getAxios) attaches IM-Authorization /
    // IM-Client-Key via its interceptor. File bytes live on signed CDN URLs that
    // authorize via the URL signature, so using it cross-origin would leak the
    // host's credentials to the CDN. Use it only for API-origin URLs; fetch CDN
    // URLs with a plain client that carries no auth (mirrors useMediaFetch).
    const client = isApiOrigin(url) ? getAxios() : axiosModule
    const resp = await client.get(url, {
      responseType: 'blob',
      onDownloadProgress: (e: AxiosProgressEvent) => {
        if (isUnmounted) return
        const { total } = e
        if (!total) return
        imkit.mergeInto('downloadProgresses', {
          [url]: e.loaded / total
        })
      }
    })

    const blobUrl = window.URL.createObjectURL(resp.data)
    const a = document.createElement('a')
    a.href = blobUrl
    a.download = joinFileName(fileName, fileExtension)
    document.body.appendChild(a)
    a.click()

    document.body.removeChild(a)
    window.URL.revokeObjectURL(blobUrl)

    if (!isUnmounted) downloadState.value = 'idle'
  } catch (error) {
    console.error(error)
    if (isUnmounted) return
    downloadState.value = 'error'
    errorTimer = setTimeout(() => {
      errorTimer = null
      if (isUnmounted) return
      downloadState.value = 'idle'
    }, 2000)
  } finally {
    if (!isUnmounted) {
      imkit.dropFrom('downloadProgresses', props.message.url)
    }
  }
}

onUnmounted(() => {
  isUnmounted = true
  if (errorTimer) {
    clearTimeout(errorTimer)
    errorTimer = null
  }
})

const html = computed((): string => {
  const keyword = imkit.messageSearchKeyword
  // `fileName` and `fileExtension` originate from peer-supplied message
  // `extra` payload — HTML-escape before interpolating into v-html content
  // to prevent stored XSS.
  const safeName = escapeHtml(
    joinFileName(props.message.fileName, props.message.fileExtension)
  )
  return highlightHtmlText(`<span>${safeName}</span>`, keyword)
})
</script>

<template>
  <!-- `py-1.5` on top of the bubble wrapper's own `py-2.5` (MessageCell.vue)
       gives the file bubble 16px of vertical breathing room instead of 10px
       — this bubble reads too cramped at the shared text-message padding.
       Added here rather than in MessageCell.vue's `messageBlockClass` so it
       stays scoped to File and doesn't change any other bubble type. -->
  <div class="relative flex items-center gap-3 overflow-hidden py-1.5">
    <!--
      While an upload is in flight the ring takes the FILE-TYPE ICON'S
      place inside this box, rather than floating over the bubble as a
      free-standing overlay. The overlay version was centred on the whole
      bubble, so it sat off to one side of the 44px icon box and over the
      filename — it read as crooked because it was not aligned to anything.
      Sharing the icon's box means it inherits an anchor that is already
      correct, and the bubble's geometry stops mattering. The icon is
      hidden while it shows: two glyphs stacked in one 44px box would
      collide, and the icon says nothing the ring does not.

      The box caps the ring at 44px, which is why the label here is a bare
      number: `100%` measures 32.9px at `text-xs` against a 34px inner
      circle (0.97x) and would spill, while `100` is 21.3px (0.63x). Same
      constraint and same resolution as the download ring below, which
      lives in an identically-sized button.

      COLOURS — this is the diagnosis ImageMessageContent.vue and
      MixedMessageContent.vue refer back to. Neither ring colour may be set
      by a class: RadialProgress writes them onto SVG presentation
      attributes (`stroke`, `stop-color`), which no class reaches. They are
      passed as `var(--color-*)` strings instead, which works because
      presentation attributes are parsed as CSS values — verified in the
      browser rather than assumed. Left unset, the track falls back to the
      package's own hardcoded `#2F495E`, a colour from its demo unrelated
      to this palette; that stray dark ring, not any scrim, was the "dark
      circle behind the spinner" bug. The arc's former `#60a5fa` was the
      same class of defect pointing the other way — an off-palette hex that
      ignored the colour preset — and is now `accent-vivid`, the
      spinner-fill role.

      There is deliberately no darkening scrim here, unlike the two sibling
      components: theirs dims a real photo behind the ring, whereas this
      ring sits on a flat `surface-muted` box with nothing to dim. That is
      also why the label is a plain `text-content` and not the `text-white`
      the scrim-backed rings use — white on this box would be unreadable in
      light mode.
    -->
    <!--
      `surface-sunken`, not `surface-muted`. This well sits on a message
      bubble, and what makes it read as a well is a LIGHTNESS step — a patch
      that differs only in chroma reads as a tint, not a box. Measured in
      OKLCH L against the four bubble/mode combinations (dark received, dark
      own, light received, light own):

        surface-muted   -0.002  -0.031  -0.017  +0.092
        surface-sunken  +0.063  +0.035  -0.034  +0.074

      The first cell is the one that broke: -0.002 is no step at all, so once
      the dark received bubble gained chroma of its own the box disappeared
      into it. Note dE alone would have said the opposite — it RISES from 2.2
      to 5.0 there — because all of that difference is chroma.
    -->
    <div
      class="flex h-11 w-11 shrink-0 items-center justify-center rounded-md bg-surface-sunken"
    >
      <RadialProgress
        v-if="message.url === '' && message.status !== MessageStatus.Failed"
        data-testid="file-upload-progress"
        :diameter="40"
        :completed-steps="uploadPercent"
        :total-steps="100"
        :start-color="'var(--color-accent-vivid)'"
        :stop-color="'var(--color-accent-vivid)'"
        :stroke-width="3"
        :inner-stroke-width="3"
        :inner-stroke-color="'var(--color-border)'"
      >
        <span class="text-xs font-medium text-content">{{
          uploadPercent
        }}</span>
      </RadialProgress>
      <component :is="fileIcon" v-else :size="22" class="text-content-muted" />
    </div>
    <div class="flex min-w-0 flex-1 flex-col gap-1 font-normal">
      <div class="multiline-ellipsis text-base font-medium" v-html="html"></div>
      <div class="text-xs" :class="{ 'text-content-subtle': isIncoming }">
        {{ $t('fileSize') }}: {{ fileSize }}
      </div>
    </div>
    <button
      v-if="message.url !== ''"
      type="button"
      class="flex h-11 w-11 shrink-0 cursor-pointer items-center justify-center rounded-full hover:bg-black/5 disabled:cursor-not-allowed dark:hover:bg-white/10"
      :disabled="downloadState !== 'idle'"
      :aria-label="$t('download')"
      @click="download"
    >
      <Download
        v-if="downloadState === 'idle'"
        :size="20"
        class="text-content-muted"
      />
      <!--
        Colours come through as `var(--color-*)` STRINGS rather than classes:
        RadialProgress writes these props straight onto SVG presentation
        attributes (`stroke`, `stop-color`), and those are parsed as CSS
        values, so `var()` resolves against the element's own cascade and
        stays theme-aware. Verified in-browser, not assumed. `accent-vivid`
        is the foreground/spinner-fill role and `border` the hairline/track
        role, per the token table in CLAUDE.md.

        No `%` on THIS ring, unlike the upload ring below. It is capped at
        36px by its own `h-11 w-11` (44px) button, leaving a 30px inner
        circle, and `100%` measures 32.9px at `text-xs` — i.e. 1.10x the
        inner diameter, so it visibly spilled past the ring. `.vrp__inner`
        sets no `overflow`, so nothing clipped it. Dropping the glyph takes
        the string to 21.3px (0.71x), which fits with room to spare. The
        unit is recoverable from the arc itself; shrinking the digits below
        `text-xs` was not an option, since that is already the smallest of
        the three type levels.
      -->
      <RadialProgress
        v-else-if="downloadState === 'downloading'"
        :diameter="36"
        :completed-steps="downloadPercent"
        :total-steps="100"
        :start-color="'var(--color-accent-vivid)'"
        :stop-color="'var(--color-accent-vivid)'"
        :stroke-width="3"
        :inner-stroke-width="3"
        :inner-stroke-color="'var(--color-border)'"
      >
        <span class="text-xs font-medium text-content-muted">
          {{ downloadPercent }}
        </span>
      </RadialProgress>
      <AlertTriangle v-else :size="20" class="text-danger-vivid" />
    </button>
  </div>
</template>

<style scoped>
.multiline-ellipsis {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  overflow-wrap: break-word;
  text-overflow: ellipsis;
}
</style>
