<script setup lang="ts">
import { ImageOff, VideoOff } from 'lucide-vue-next'
import type { StyleValue } from 'vue'
import { onBeforeUnmount, ref, watch } from 'vue'
import {
  fetchImageAsBase64,
  refreshS3PresignedUrl,
  resolveFilesProxyUrl
} from '../../composables/useMediaFetch'
import { getAxios } from '../../runtime/axios'
import {
  addImageFailure,
  imageCache,
  imageFailuresRef,
  removeImageFailure
} from '../../runtime/caches'
import {
  dropSignedUrl,
  getSignedUrl,
  isOnCooldown,
  markCooldown,
  setSignedUrl
} from '../../runtime/signedUrlStore'
import { useImkitStore } from '../../stores/imkit'

type LoadState = 'idle' | 'loading' | 'loaded' | 'failed'

const props = withDefaults(
  defineProps<{
    url: string
    alt?: string
    variant?: 'thumb' | 'full'
    kind?: 'image' | 'video'
    imgClass?: string
    imgStyle?: StyleValue
    noCallout?: boolean
  }>(),
  {
    alt: '',
    variant: 'thumb',
    kind: 'image',
    imgClass: '',
    imgStyle: () => ({}),
    noCallout: false
  }
)

const emit = defineEmits<{
  (e: 'load'): void
  (e: 'error'): void
  (e: 'retry'): void
}>()

const imkit = useImkitStore()
const imageFailures = imageFailuresRef

const resolvedSrc = ref<string>('')
const state = ref<LoadState>('idle')
const triedFallbackRef = ref(false)

let loadToken = 0
let alive = true
// Tracks the URL whose progress entry is currently live in the store so we can
// drop it on cancellation/unmount even when load() never reaches its own
// terminal cleanup (e.g. a fetch promise that never settles).
let pendingProgressUrl: string | null = null

const clearProgress = (url: string) => {
  imkit.dropFrom('downloadProgresses', url)
  if (pendingProgressUrl === url) pendingProgressUrl = null
}

onBeforeUnmount(() => {
  alive = false
  if (pendingProgressUrl) clearProgress(pendingProgressUrl)
})

const isValidUrl = (value: string): boolean => {
  if (!value) return false
  try {
    new URL(value, window.location.href)
    return true
  } catch {
    return false
  }
}

const load = async (url: string) => {
  const token = ++loadToken

  if (!url) {
    state.value = 'failed'
    emit('error')
    return
  }
  if (url.startsWith('data:')) {
    resolvedSrc.value = url
    state.value = 'loaded'
    emit('load')
    return
  }
  if (!isValidUrl(url)) {
    state.value = 'failed'
    emit('error')
    return
  }
  const cached = imageCache.get(url)
  if (cached) {
    resolvedSrc.value = cached
    state.value = 'loaded'
    emit('load')
    return
  }
  const cachedSignedUrl = getSignedUrl(url)
  if (cachedSignedUrl) {
    resolvedSrc.value = cachedSignedUrl
    state.value = 'loaded'
    emit('load')
    return
  }
  if (imageFailures.value.has(url)) {
    state.value = 'failed'
    emit('error')
    return
  }

  state.value = 'loading'
  const onProgress = (ratio: number) => {
    if (!alive || token !== loadToken) return
    pendingProgressUrl = url
    imkit.mergeInto('downloadProgresses', { [url]: ratio })
  }

  // For /files/{bucket}/{id} proxy URLs, resolve to the direct storage
  // signed URL and let the browser load it natively via <img src>.
  // Bypasses the server-side pipe and avoids CORS on the storage bucket
  // (signed S3/GCS URLs often lack CORS, which blocks fetch/XHR but not
  // native image loads).
  // Run on the onImgError retry too (triedFallbackRef === true): re-resolving
  // mints a FRESH signed URL via the authenticated getAxios() and re-assigns
  // <img src>, re-attempting the fetch — this recovers a transient blip and is
  // the ONLY recovery for /files URLs. The base64/refresh fallbacks below
  // CANNOT reach /files: fetchImageAsBase64 uses plain axios (no
  // IM-Authorization, so /files 401s) and refreshS3PresignedUrl only handles
  // s3.amazonaws.com hosts. triedFallbackRef stops the 2nd onImgError, so the
  // re-resolve runs at most once per mount (no loop).
  const signedUrl = await resolveFilesProxyUrl(getAxios(), url).catch(
    () => null
  )
  if (!alive || token !== loadToken) return
  if (signedUrl) {
    clearProgress(url)
    setSignedUrl(url, signedUrl)
    resolvedSrc.value = signedUrl
    state.value = 'loaded'
    emit('load')
    return
  }

  try {
    const src = await fetchImageAsBase64(url, onProgress)
    if (!alive || token !== loadToken) return
    clearProgress(url)
    imageCache.set(url, src)
    resolvedSrc.value = src
    state.value = 'loaded'
    emit('load')
    return
  } catch {
    // fall through to S3 refresh attempt
  }

  if (!alive || token !== loadToken) return

  try {
    const fresh = await refreshS3PresignedUrl(getAxios(), url)
    if (!alive || token !== loadToken) return
    if (fresh) {
      clearProgress(url)
      setSignedUrl(url, fresh)
      resolvedSrc.value = fresh
      state.value = 'loaded'
      emit('load')
      return
    }
  } catch {
    // fall through to failed
  }

  if (!alive || token !== loadToken) return
  clearProgress(url)
  addImageFailure(url)
  state.value = 'failed'
  emit('error')
}

watch(
  () => props.url,
  (url, oldUrl) => {
    // The previous URL's load (if still in flight) is invalidated by the new
    // loadToken below, so its terminal cleanup never runs — drop its progress
    // entry here, otherwise a superseded URL leaks into downloadProgresses.
    if (oldUrl && oldUrl !== url) clearProgress(oldUrl)
    triedFallbackRef.value = false
    load(url)
  },
  { immediate: true }
)

const onImgError = () => {
  if (triedFallbackRef.value) {
    addImageFailure(props.url)
    state.value = 'failed'
    emit('error')
    return
  }
  // A native <img> render failure on a resolved signed URL is treated as a
  // transient transport error (network blip / dropped connection), NOT a
  // permanent one — regardless of how far the URL is from expiry. Drop the
  // cached signed URL and re-run load() once: load() re-resolves the /files
  // proxy via the authenticated getAxios() (see the resolver note in load),
  // minting a fresh signed URL and re-attempting the <img> fetch — that, not
  // the unauthenticated base64 fallback, recovers a /files blip. Bounded by the
  // one-shot triedFallbackRef guard (a 2nd onImgError goes straight to
  // addImageFailure) and the 30s per-URL cooldown below, so a burst of failures
  // is one re-resolve per image, not a retry storm; a genuinely deleted object
  // costs that one bounded round-trip before surfacing failure. (Reverses the
  // far-from-expiry "conservative purge" in image-http-cache-design.md:116,
  // which bricked transient failures with no recovery — the thumb variant has
  // no manual retry button at all.)
  if (isOnCooldown(props.url)) {
    addImageFailure(props.url)
    state.value = 'failed'
    emit('error')
    return
  }
  markCooldown(props.url)
  dropSignedUrl(props.url)
  triedFallbackRef.value = true
  load(props.url)
}

const retry = () => {
  removeImageFailure(props.url)
  dropSignedUrl(props.url)
  triedFallbackRef.value = false
  emit('retry')
  load(props.url)
}
</script>

<template>
  <template v-if="state === 'failed'">
    <slot name="placeholder">
      <div
        v-if="variant === 'full'"
        :class="[
          'flex flex-col items-center justify-center gap-3 bg-black/60 p-6 text-white',
          imgClass
        ]"
        :style="imgStyle"
        role="img"
        :aria-label="alt"
      >
        <component
          :is="kind === 'video' ? VideoOff : ImageOff"
          :size="64"
          class="text-white/70"
        />
        <p class="text-base">{{ $t('mediaLoadFailed') }}</p>
        <button
          type="button"
          class="cursor-pointer rounded-md bg-white/10 px-4 py-2 text-base text-white hover:bg-white/20"
          @click="retry"
        >
          {{ $t('retry') }}
        </button>
      </div>
      <div
        v-else
        :class="['flex items-center justify-center bg-surface-muted', imgClass]"
        :style="imgStyle"
        role="img"
        :aria-label="alt"
      >
        <component
          :is="kind === 'video' ? VideoOff : ImageOff"
          :size="32"
          class="text-content-faint"
        />
      </div>
    </slot>
  </template>
  <div
    v-else-if="state === 'loading'"
    :class="['bg-surface', imgClass]"
    :style="imgStyle"
    data-testid="media-img-loading"
  />
  <img
    v-else
    :src="resolvedSrc"
    :alt="alt"
    referrerpolicy="no-referrer"
    :draggable="noCallout ? false : undefined"
    :class="[
      imgClass,
      noCallout && '[-webkit-touch-callout:none] [-webkit-user-select:none]'
    ]"
    :style="imgStyle"
    data-testid="image-bubble-thumb"
    @error="onImgError"
  />
</template>
