<script setup lang="ts">
import { computed, ref } from 'vue'
import { useImkitStore } from '../stores/imkit'
const imkit = useImkitStore()
type StickerSet = {
  name: string
  number: number
}
const stickerSets: StickerSet[] = [
  { name: 'FunFunFamily', number: 40 }
  // { name: 'animal', number: 16 },
  // { name: 'emoji', number: 40 },
  // { name: 'food', number: 16 },
  // { name: 'money', number: 11 },
  // { name: 'natural', number: 30 },
  // { name: 'people', number: 16 },
  // { name: 'sport', number: 16 },
]
const selectedStickerSet = ref(stickerSets[0])
const room = computed(() => imkit.rooms[imkit.selectedRoomId])
const isSending = ref(false)
const emit = defineEmits(['close'])
const send = async (stickerId: string) => {
  // M30: guard against a double-tap firing duplicate sends before the first
  // resolves, and stop a rejected send from escaping as an unhandled rejection.
  if (isSending.value) return
  const targetRoom = room.value
  if (!targetRoom) return
  isSending.value = true
  try {
    await imkit.sendMessage({
      roomId: targetRoom.id,
      messageType: 'sticker',
      sticker: stickerId
    })
    emit('close')
  } catch (error) {
    console.error('[StickerPanel] failed to send sticker:', error)
  } finally {
    isSending.value = false
  }
}
</script>

<template>
  <div
    class="absolute right-0 bottom-[110%] flex h-80 w-80 max-w-full flex-col divide-y overflow-auto rounded-lg bg-surface shadow-raised"
  >
    <div
      class="grid grow grid-cols-3 items-center justify-center gap-4 overflow-y-auto p-4 sm:grid-cols-4"
    >
      <img
        v-for="i in selectedStickerSet.number"
        :key="i"
        :src="`/sticker/${selectedStickerSet.name}/${selectedStickerSet.name}-${i}.png`"
        class="aspect-square w-full cursor-pointer border-0 object-contain"
        @click="send(`${selectedStickerSet.name}-${i}`)"
      />
    </div>
    <div
      v-if="stickerSets.length > 1"
      class="flex h-14 w-full shrink-0 gap-4 overflow-x-auto p-3"
    >
      <img
        v-for="stickerSet in stickerSets"
        :key="stickerSet.name"
        :src="`/sticker/${stickerSet.name}/${stickerSet.name}-1.png`"
        class="h-full cursor-pointer border-0 object-contain"
        @click="selectedStickerSet = stickerSet"
      />
    </div>
  </div>
</template>

<style scoped></style>
