<script setup lang="ts">
import dayjs from 'dayjs'
import localizedFormat from 'dayjs/plugin/localizedFormat'
import { Check } from 'lucide-vue-next'
import { computed } from 'vue'
import { useImkitStore } from '../../stores/imkit'
import Room from './../../classes/room'
import AvatarView from './../AvatarView.vue'
dayjs.extend(localizedFormat)
const props = defineProps<{ source: Room }>()
const imkit = useImkitStore()

const isSelected = computed(
  () => !!imkit.selectedRoomIdsForCreateFolder[props.source.id]
)
const toggleRoom = (selected: boolean) => {
  if (selected) {
    imkit.mergeInto('selectedRoomIdsForCreateFolder', {
      [props.source.id]: new Date()
    })
    return
  }
  delete imkit.selectedRoomIdsForCreateFolder[props.source.id]
}
</script>

<template>
  <!--
    Square, full-bleed fill: no corner radius, so consecutive selected (or
    hovered) rows read as one unbroken block instead of showing notches
    where two rounded corners meet. The hover/selected fill is
    `surface-muted`, the same theme-aware token every other row hover in
    this SDK uses, not a raw grey that ignores the blue-tinted dark panel.
  -->
  <div
    data-testid="room-cell"
    class="group relative flex min-h-11 w-full cursor-pointer items-center gap-3 p-1 px-2 sm:hover:bg-surface-hover"
    :class="{
      'bg-surface-muted': isSelected
    }"
    @click="toggleRoom(!isSelected)"
  >
    <!--
      Checkbox glyph matches the reference picklist spec (18x18, rounded-sm,
      1.5px border; checked = filled accent with a white check) instead of
      the previous Check/Square icon swap, which used a raw `text-green-500`
      for the checked state rather than a token. It sits before the avatar,
      matching the reference row order (checkbox, avatar, name).
    -->
    <span
      class="flex h-[18px] w-[18px] shrink-0 items-center justify-center rounded-sm border-[1.5px] transition-colors"
      :class="
        isSelected ? 'border-accent bg-accent' : 'border-border bg-surface'
      "
    >
      <Check v-if="isSelected" :size="13" class="text-white" stroke-width="3" />
    </span>
    <!--
      Group rooms render as ONE message-glyph avatar, same as the main room
      list — so this room picker matches the list it is picking from. The
      stacked pair and its separator ring are deleted, not left dormant:
      that stack was the only overlap here, and avatars carry no border or
      ring in this component now.
    -->
    <!-- Cover when set, group glyph as the fallback — see the note on the
         same expression in RoomCell.vue for why a group uses `coverUrl`
         rather than `avatars[0]`. -->
    <avatar-view
      :url="source.isGroup ? source.coverUrl : source.avatars[0].url"
      :name="
        source.isGroup ? (source.displayName ?? '') : source.avatars[0].name
      "
      :is-group="source.isGroup"
      class="h-[34px] w-[34px] shrink-0 text-base"
    />
    <div class="flex w-0 min-w-0 grow flex-col text-left">
      <div
        class="overflow-hidden text-base text-ellipsis whitespace-nowrap text-content"
      >
        {{ source.displayName }}
      </div>
    </div>
  </div>
</template>

