<script>
import {
  applyRange,
  closest,
  getAtAndIndex,
  getOffset,
  getPrecedingRange,
  getRange,
  scrollIntoView,
  shouldShowMentionPanel
} from './util'

export default {
  name: 'VueAt',
  props: {
    value: {
      type: String, // value not required
      default: null
    },
    at: {
      type: String,
      default: null
    },
    ats: {
      type: Array,
      default: () => ['@']
    },
    suffix: {
      type: String,
      default: ' '
    },
    loop: {
      type: Boolean,
      default: true
    },
    allowSpaces: {
      type: Boolean,
      default: true
    },
    tabSelect: {
      type: Boolean,
      default: false
    },
    avoidEmail: {
      type: Boolean,
      default: true
    },
    showUnique: {
      type: Boolean,
      default: true
    },
    hoverSelect: {
      type: Boolean,
      default: true
    },
    members: {
      type: Array,
      default: () => []
    },
    nameKey: {
      type: String,
      default: ''
    },
    filterMatch: {
      type: Function,
      default: (name, chunk) => {
        // match at lower-case
        return name.toLowerCase().indexOf(chunk.toLowerCase()) > -1
      }
    },
    deleteMatch: {
      type: Function,
      default: (name, chunk, suffix) => {
        return chunk === name + suffix
      }
    },
    scrollRef: {
      type: String,
      default: ''
    }
  },
  emits: ['update:value', 'at', 'insert'],

  data() {
    return {
      // at[v-model] mode should be on only when
      // initial :value/v-model is present (not nil)
      bindsValue: this.value != null,
      customsEmbedded: false,
      hasComposition: false,
      atwho: null,
      panelJustOpened: false,
      openTimer: null
    }
  },
  computed: {
    atItems() {
      return this.at ? [this.at] : this.ats
    },

    currentItem() {
      if (this.atwho) {
        return this.atwho.list[this.atwho.cur]
      }
      return ''
    },

    style() {
      if (this.atwho) {
        const { x, y } = this.atwho
        const { wrap } = this.$refs
        if (wrap) {
          const offset = getOffset(wrap)
          const scrollEl = this.scrollRef
            ? document.querySelector(this.scrollRef)
            : null
          const scrollLeft = scrollEl ? scrollEl.scrollLeft : 0
          const scrollTop = scrollEl ? scrollEl.scrollTop : 0
          const left = x + scrollLeft + window.pageXOffset - offset.left + 'px'
          const top = y + scrollTop + window.pageYOffset - offset.top + 'px'
          return { left, top }
        }
      }
      return null
    }
  },
  watch: {
    'atwho.cur'(index) {
      if (index != null) {
        // cur index exists
        this.$nextTick(() => {
          this.scrollToCur()
        })
      }
    },
    members() {
      this.handleInput(true)
    },
    value(value) {
      if (this.bindsValue) {
        this.handleValueUpdate(value)
      }
    }
  },
  mounted() {
    // vue3 migration.5
    // [Vue warn]: (deprecation INSTANCE_SCOPED_SLOTS) vm.$scopedSlots has been removed. Use vm.$slots instead.
    // Details: https://v3-migration.vuejs.org/breaking-changes/slots-unification.html
    if (this.$slots.embeddedItem) {
      this.customsEmbedded = true
    }
    if (this.bindsValue) {
      this.handleValueUpdate(this.value)
    }
  },

  beforeUnmount() {
    if (this.openTimer) {
      clearTimeout(this.openTimer)
      this.openTimer = null
    }
  },

  methods: {
    itemName(v) {
      const { nameKey } = this
      return nameKey ? v[nameKey] : v
    },
    isCur(index) {
      return index === this.atwho.cur
    },
    handleValueUpdate(value) {
      const el = this.$el.querySelector('[contenteditable]')
      if (value !== el.innerHTML) {
        // avoid range reset
        el.innerHTML = value
        this.dispatchInput()
      }
    },
    dispatchInput() {
      let el = this.$el.querySelector('[contenteditable]')
      let ev = new Event('input', { bubbles: true })
      el.dispatchEvent(ev)
    },

    handleItemHover(e) {
      if (this.hoverSelect && !this.panelJustOpened) {
        this.selectByMouse(e)
      }
    },
    handleItemClick(e) {
      this.selectByMouse(e)
      this.insertItem()
    },
    handleBeforeInput(e) {
      if (!this.customsEmbedded || e.inputType !== 'deleteContentBackward')
        return

      const embedded = this.findPrecedingEmbedded()
      if (embedded) {
        e.preventDefault()
        e.stopPropagation()
        this.removeEmbedded(embedded)
      }
    },
    removeEmbedded(embedded) {
      // Place cursor before the embedded element, then remove it via DOM API.
      // Using embedded.remove() instead of Range.deleteContents() avoids issues
      // when the range crosses contenteditable="false" boundaries (iOS Safari).
      const r = document.createRange()
      r.setStartBefore(embedded)
      r.collapse(true)
      applyRange(r)
      embedded.remove()
      this.handleInput()
    },
    findPrecedingEmbedded() {
      const range = getRange()
      if (!range || !range.collapsed) return null

      const { startContainer, startOffset } = range

      const editableEl = this.$el.querySelector('[contenteditable]')
      if (!editableEl) return null

      // Case 1: Cursor is inside an embedded element (iOS Safari quirk)
      let el = startContainer
      while (el && el !== editableEl) {
        if (
          el.nodeType === Node.ELEMENT_NODE &&
          el.hasAttribute('data-at-embedded')
        ) {
          return el
        }
        el = el.parentNode
      }

      // Find the node just before the cursor
      let node = null
      if (startContainer.nodeType === Node.TEXT_NODE) {
        if (startOffset === 0) {
          node = startContainer.previousSibling
        }
      } else if (
        startContainer.nodeType === Node.ELEMENT_NODE &&
        startOffset > 0
      ) {
        node = startContainer.childNodes[startOffset - 1]
      }

      // Case 2: Walk backwards, skipping whitespace-only text nodes
      while (
        node &&
        node.nodeType === Node.TEXT_NODE &&
        /^\s*$/.test(node.data)
      ) {
        node = node.previousSibling
      }

      if (
        node &&
        node.nodeType === Node.ELEMENT_NODE &&
        node.hasAttribute('data-at-embedded')
      ) {
        return node
      }

      return null
    },
    handleDelete(e) {
      if (this.customsEmbedded) {
        const embedded = this.findPrecedingEmbedded()
        if (embedded) {
          e.preventDefault()
          e.stopPropagation()
          this.removeEmbedded(embedded)
        }
        return
      }

      const range = getPrecedingRange()
      if (range) {
        const { atItems, members, suffix, deleteMatch, itemName } = this
        const text = range.toString()
        const { at, index } = getAtAndIndex(text, atItems)

        if (index > -1) {
          const chunk = text.slice(index + at.length)
          const has = members.some((v) => {
            const name = itemName(v)
            return deleteMatch(name, chunk, suffix)
          })
          if (has) {
            e.preventDefault()
            e.stopPropagation()
            const r = getRange()
            if (r) {
              r.setStart(r.endContainer, index)
              r.deleteContents()
              applyRange(r)
              this.handleInput()
            }
          }
        }
      }
    },
    handleKeyDown(e) {
      const { atwho } = this
      if (atwho) {
        if (e.keyCode === 38 || e.keyCode === 40) {
          // ↑/↓
          if (!(e.metaKey || e.ctrlKey)) {
            e.preventDefault()
            e.stopPropagation()
            this.selectByKeyboard(e)
          }
          return
        }
        if (e.keyCode === 13 || (this.tabSelect && e.keyCode === 9)) {
          // enter or tab
          e.preventDefault()
          e.stopPropagation()
          this.insertItem()
          return
        }
        if (e.keyCode === 27) {
          // esc
          this.closePanel()
          return
        }
      }

      const isBackspace = e.keyCode === 8 || e.key === 'Backspace'
      if (isBackspace) {
        this.handleDelete(e)
      }
    },

    // compositionStart -> input -> compositionEnd
    handleCompositionStart() {
      this.hasComposition = true
    },
    handleCompositionEnd() {
      this.hasComposition = false
      this.handleInput()
    },
    handleInput(keep) {
      if (this.hasComposition) return
      const el = this.$el.querySelector('[contenteditable]')

      if (
        el.textContent.trim() === '' &&
        !el.querySelector('[data-at-embedded]')
      ) {
        while (el.firstChild) el.firstChild.remove()
      }

      // vue3 migration.2.1
      // https://vuejs.org/guide/components/events.html#usage-with-v-model
      // https://laracasts.com/discuss/channels/vue/how-do-emit-to-v-model-in-vue-3
      // this.$emit('input', el.innerHTML)
      this.$emit('update:value', el.innerHTML)

      const range = getPrecedingRange()
      if (range) {
        const { atItems, allowSpaces, showUnique } = this

        let show = true
        const text = range.toString()

        const { at, index } = getAtAndIndex(text, atItems)

        if (index < 0) show = false
        const prev = text[index - 1]
        const chunk = text.slice(index + at.length, text.length)

        if (show) {
          show = shouldShowMentionPanel({ prev, chunk, allowSpaces })
        }

        if (!show) {
          this.closePanel()
        } else {
          const { members, filterMatch, itemName } = this
          if (!keep && chunk) {
            // fixme: should be consistent with AtTextarea.vue
            this.$emit('at', chunk)
          }
          const matched = members.filter((v) => {
            const name = itemName(v)
            return filterMatch(name, chunk, at)
          })

          show = false
          if (matched.length) {
            show = true
            if (!showUnique) {
              let item = matched[0]
              if (chunk === itemName(item)) {
                show = false
              }
            }
          }

          if (show) {
            this.openPanel(matched, range, index, at)
          } else {
            this.closePanel()
          }
        }
      }
    },

    closePanel() {
      if (this.openTimer) {
        clearTimeout(this.openTimer)
        this.openTimer = null
      }
      if (this.atwho) {
        this.atwho = null
      }
    },
    openPanel(list, range, offset, at) {
      const isFirstOpen = !this.atwho
      const fn = () => {
        this.openTimer = null
        const r = range.cloneRange()
        r.setStart(r.endContainer, offset + at.length) // 从@后第一位开始
        // todo: 根据窗口空间 判断向上或是向下展开
        const rect = r.getClientRects()[0]
        if (!rect) {
          // The panel never opened; clear the just-opened guard so hover-select
          // is not left disabled until the next successful open.
          if (isFirstOpen) this.panelJustOpened = false
          return
        }
        this.atwho = {
          range,
          offset,
          list,
          x: rect.left,
          y: rect.top - 4,
          cur: 0
        }
        if (isFirstOpen) {
          this.$nextTick(() => {
            setTimeout(() => {
              this.panelJustOpened = false
            }, 50)
          })
        }
      }
      if (this.atwho) {
        fn()
      } else {
        this.panelJustOpened = true
        // 焦点超出了显示区域 需要提供延时以移动指针 再计算位置
        this.openTimer = setTimeout(fn, 10)
      }
    },

    scrollToCur() {
      // vue3 migration.6
      // fix: [Vue warn]: Missing ref owner context. ref cannot be used on hoisted vnodes.
      // A vnode with ref must be created inside the render function.
      // at selectByMouse
      // at handleItemHover
      // const curEl = this.$refs.cur[0]
      let { wrap } = this.$refs
      let { cur } = this.atwho
      const curEl = wrap.querySelector(`.atwho-li[data-index="${cur}"]`)

      const scrollParent = curEl.parentElement.parentElement // .atwho-view
      scrollIntoView(curEl, scrollParent)
    },
    selectByMouse(e) {
      const el = closest(e.target, (d) => {
        return d.getAttribute('data-index')
      })
      const cur = +el.getAttribute('data-index')
      this.atwho = {
        ...this.atwho,
        cur
      }
    },
    selectByKeyboard(e) {
      const offset = e.keyCode === 38 ? -1 : 1
      const { cur, list } = this.atwho
      const nextCur = this.loop
        ? (cur + offset + list.length) % list.length
        : Math.max(0, Math.min(cur + offset, list.length - 1))
      this.atwho = {
        ...this.atwho,
        cur: nextCur
      }
    },

    // todo: 抽离成库并测试
    insertText(text, r) {
      r.deleteContents()
      const node = r.endContainer
      if (node.nodeType === Node.TEXT_NODE) {
        const cut = r.endOffset
        node.data = node.data.slice(0, cut) + text + node.data.slice(cut)
        r.setEnd(node, cut + text.length)
      } else {
        const t = document.createTextNode(text)
        r.insertNode(t)
        r.setEndAfter(t)
      }
      r.collapse(false) // 参数在IE下必传
      applyRange(r)
      this.dispatchInput()
    },

    insertHtml(html, r) {
      r.deleteContents()
      const node = r.endContainer
      const newElement = document.createElement('span')

      // Seems `contentediable=false` should includes spaces,
      // otherwise, caret can't be placed well across them
      newElement.appendChild(document.createTextNode(' '))
      newElement.appendChild(this.htmlToElement(html))
      newElement.appendChild(document.createTextNode(' '))
      newElement.setAttribute('data-at-embedded', '')
      newElement.setAttribute('contenteditable', false)

      if (node.nodeType === Node.TEXT_NODE) {
        const cut = r.endOffset
        let secondPart = node.splitText(cut)
        node.parentNode.insertBefore(newElement, secondPart)
        // Ensure there's an editable text node after the embedded span for proper IME handling
        // Without this, the cursor lands right after contenteditable="false" which breaks IME composition
        if (!secondPart.data) {
          secondPart.data = this.suffix
        }
        r.setStart(secondPart, 0)
        r.setEnd(secondPart, 0)
      } else {
        const t = document.createTextNode(this.suffix)
        r.insertNode(newElement)
        r.setEndAfter(newElement)
        r.insertNode(t)
        r.setEndAfter(t)
      }
      r.collapse(false) // 参数在IE下必传
      applyRange(r)
    },

    insertItem() {
      const { range, list, cur } = this.atwho
      const { suffix, atItems, itemName, customsEmbedded } = this
      const r = range.cloneRange()
      const text = range.toString()
      const { at, index } = getAtAndIndex(text, atItems)

      // Leading `@` is automatically dropped as `customsEmbedded=true`
      // You can fully custom the output inside the embedded slot
      const start = customsEmbedded ? index : index + at.length
      r.setStart(r.endContainer, start)

      // hack: 连续两次 可以确保click后 focus回来 range真正生效
      applyRange(r)
      applyRange(r)
      const curItem = list[cur]

      if (customsEmbedded) {
        // `suffix` is ignored as `customsEmbedded=true` has to be
        // wrapped around by spaces

        // vue3 migration.7
        // fix: Uncaught TypeError: Cannot read properties of undefined (reading 'innerHTML')
        // at Proxy.insertItem (At.vue?075e:490:1)
        // at Proxy.handleItemClick (At.vue?075e:184:1)
        // const html = this.$refs.embeddedItem.firstChild.innerHTML
        const html = this.$refs.embeddedItem.firstElementChild.innerHTML

        this.insertHtml(html, r)
      } else {
        const t = itemName(curItem) + suffix
        this.insertText(t, r)
      }
      scrollIntoView(window.getSelection())

      this.$emit('insert', curItem)
      this.handleInput()

      // fix safari: use `r` instead of `window.getSelection()`
      // scrollIntoView(window.getSelection())
      scrollIntoView(r)
    },
    htmlToElement(html) {
      const template = document.createElement('template')
      html = html.trim() // Never return a text node of whitespace as the result
      template.innerHTML = html
      return template.content.firstChild
    }
  }
}
</script>
<template>
  <div
    ref="wrap"
    class="atwho-wrap"
    @compositionstart="handleCompositionStart"
    @compositionend="handleCompositionEnd"
    @input="handleInput()"
    @beforeinput="handleBeforeInput"
    @keydown.capture="handleKeyDown"
  >
    <div v-if="atwho" class="atwho-panel" :style="style">
      <div class="atwho-inner">
        <div class="atwho-view">
          <ul class="atwho-ul">
            <li
              v-for="(item, index) in atwho.list"
              :key="index"
              class="atwho-li"
              :class="isCur(index) && 'atwho-cur'"
              :data-index="index"
              @mousedown.prevent
              @mouseenter="handleItemHover"
              @click="handleItemClick"
            >
              <slot name="item" :item="item">
                <span v-text="itemName(item)" />
              </slot>
            </li>
          </ul>
        </div>
      </div>
    </div>
    <span v-show="false" ref="embeddedItem">
      <slot name="embeddedItem" :current="currentItem" />
    </span>
    <slot />
  </div>
</template>

<style lang="scss">
.atwho-wrap {
  position: relative;
}

.atwho-panel {
  position: absolute;
  // 入場動畫
  animation: atwho-fade-in 0.15s ease-out;
}

.atwho-inner {
  position: relative;
}

.atwho-view {
  position: absolute;
  bottom: 0;
  left: -0.8em;
  z-index: 11110 !important;
  cursor: default;
  min-width: 160px;
  max-width: 220px;
  max-height: 200px;
  overflow-y: auto;
  overflow-x: hidden;

  // Design-token fill/border/shadow, matching the rest of the app's
  // floating-menu convention (see tribo/ui/dropdown-menu.ts: bg-surface,
  // border-border, shadow-raised). `@apply` cannot reach a project token
  // inside a <style> block here — this block compiles without `@theme` and
  // fails with "Cannot apply unknown utility class" — so these read the
  // custom properties directly. The SDK root derives them from the configured
  // seeds, so var() follows both the palette and colour mode without a local
  // dark branch.
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 12px;
  box-shadow: var(--shadow-raised);

  // 文字樣式
  color: var(--color-content);
  font-size: 15px;
  font-weight: 400;
  letter-spacing: -0.01em;

  // 滾動條樣式
  &::-webkit-scrollbar {
    width: 6px;
  }
  &::-webkit-scrollbar-track {
    background: transparent;
    margin: 4px 0;
  }
  &::-webkit-scrollbar-thumb {
    background: var(--color-border-strong);
    border-radius: 3px;
    &:hover {
      background: var(--color-content-muted);
    }
  }
}

.atwho-ul {
  list-style: none;
  padding: 6px;
  margin: 0;
  max-height: 180px;
}

.atwho-li {
  box-sizing: border-box;
  height: 34px;
  padding: 0 12px;
  margin: 2px 0;
  white-space: nowrap;
  display: flex;
  align-items: center;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.12s ease;

  span {
    overflow: hidden;
    text-overflow: ellipsis;
  }

  &:hover:not(.atwho-cur) {
    background: var(--color-accent-subtle);
  }
}

// Solid `accent` fill with white text, not the old fixed blue gradient —
// `accent` is the background role already verified to carry white text at
// >=4.5:1 across supported palettes and colour modes (tests/tokenContrast.test.ts), so
// this is the same pair `bg-accent`/`text-white` uses everywhere else
// rather than a new, unverified combination. `accent-subtle` (used for
// plain hover above) was rejected for the *selected* state specifically:
// an achromatic `brand` seed has no chromatic accent, so a subtle tint plus
// unchanged text reads as barely-there rather than selected, the same
// reasoning `style.css` documents for RoomCell's selected-row ring.
.atwho-cur {
  background: var(--color-accent);
  color: white;
}

// 入場動畫
@keyframes atwho-fade-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
</style>
