<script setup lang="ts">
import { computed } from 'vue'
import { useVfm } from 'vue-final-modal'
import Callbacks from '../classes/callbacks'
import { getConfig } from '../runtime/config'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

const vfm = useVfm()
const config = getConfig()
const callbacks = computed((): Callbacks => config.callbacks)

const handleConfirm = () => {
  // The SDK runs on the host page's origin, so localStorage.clear() would wipe
  // the host app's own keys and log its user out. Remove only imkit's keys.
  // Iterate backwards so in-place removals don't shift indices we still visit.
  for (let i = localStorage.length - 1; i >= 0; i--) {
    const key = localStorage.key(i)
    if (key?.startsWith('imkit-')) localStorage.removeItem(key)
  }
  callbacks.value.onEndChat?.()
  vfm.closeAll()
}

const handleCancel = () => {
  vfm.closeAll()
}
</script>

<template>
  <ConfirmDialogShell
    :title="$t('endChatConfirmTitle')"
    :cancel-label="$t('cancel')"
    :confirm-label="$t('confirm')"
    confirm-test-id="end-chat-confirm-action"
    @cancel="handleCancel"
    @confirm="handleConfirm"
  >
    {{ $t('endChatConfirmMessage') }}
  </ConfirmDialogShell>
</template>
