import type IMImage from '../classes/image'
import Message, {
  ImageMessage,
  MessageType,
  MixedMessage,
  VideoMessage
} from '../classes/message'
import type IMVideo from '../classes/video'

type ImageMediaMessage = ImageMessage | MixedMessage

type RoomMediaMetadata = {
  key: string
  messageId: string
  roomId: string
  senderName: string
  createdAt: number
}

export type RoomMediaItem =
  | (RoomMediaMetadata & {
      kind: 'image'
      imageIndex: number
      image: IMImage
    })
  | (RoomMediaMetadata & {
      kind: 'video'
      video: IMVideo
    })

export function collectRoomMediaItems(
  messages: readonly Message[]
): RoomMediaItem[] {
  const items = messages.flatMap((message): RoomMediaItem[] => {
    const metadata = {
      messageId: message.id,
      roomId: message.roomId,
      senderName: message.senderNickname,
      createdAt: message.createdAt
    }

    if (
      message.type === MessageType.Image ||
      message.type === MessageType.Mixed
    ) {
      const imageMessage = message as ImageMediaMessage
      return imageMessage.images.map((image, imageIndex) => ({
        ...metadata,
        kind: 'image',
        key: `${message.id}:image:${imageIndex}:${image.id}`,
        imageIndex,
        image
      }))
    }
    if (message.type === MessageType.Video) {
      const videoMessage = message as VideoMessage
      return [
        {
          ...metadata,
          kind: 'video',
          key: `${message.id}:video:${videoMessage.video.id}`,
          video: videoMessage.video
        }
      ]
    }
    return []
  })

  return items.sort((a, b) => b.createdAt - a.createdAt)
}
