// Validate dimensional style values: only allow numeric values with safe CSS units.
// Rejects viewport-relative units (vw/vh/vmin/vmax) and raw expressions to prevent
// peer-controlled payloads from escaping the bubble bounds.
const SAFE_LEN = /^\d+(\.\d+)?(px|%|em|rem)?$/
export const safeLen = (v: unknown): string | undefined =>
  typeof v === 'string' && SAFE_LEN.test(v) ? v : undefined

// Validate CSS color values: hex, rgb/rgba, hsl/hsla, and named colors.
const SAFE_COLOR =
  /^(#[0-9a-fA-F]{3,8}|rgba?\([\d.,\s%]+\)|hsla?\([\d.,\s%]+\)|[a-zA-Z]+)$/
export const safeColor = (v: unknown): string | undefined =>
  typeof v === 'string' && SAFE_COLOR.test(v) ? v : undefined
