/* eslint-disable @typescript-eslint/no-explicit-any */

import dayjs from 'dayjs'
import { Play } from 'lucide-vue-next'
import {
  defineComponent,
  h,
  onBeforeUnmount,
  onMounted,
  ref,
  type PropType
} from 'vue'
import { useImkitStore } from '../../../stores/imkit'
import { cn, type ClassValue } from '../utils'

export default defineComponent({
  name: 'LazyMedia',
  inheritAttrs: false,
  props: {
    bucketName: { type: String, default: '' },
    fileId: { type: String, default: '' },
    previewFileId: { type: String, default: '' },
    alt: { type: String, default: '' },
    type: { type: String, required: true },
    sender: { type: String, default: '' },
    date: { type: String, default: '' },
    onClick: { type: Function as PropType<() => void>, required: true },
    class: { type: null, default: undefined }
  },
  setup(props, { attrs }) {
    const imkit = useImkitStore()
    const isLoaded = ref(false)
    const isInView = ref(false)
    const btnRef = ref<HTMLButtonElement | null>(null)

    let observer: IntersectionObserver | null = null

    const presignedUrl = ref<string | null>(null)

    // Check if video has a preview thumbnail
    const hasVideoPreview = () =>
      props.type === 'video' && Boolean(props.previewFileId)

    const fetchPresigned = async () => {
      try {
        // For video with preview, use previewFileId; otherwise use fileId (video itself)
        const targetFileId =
          props.type === 'video' && props.previewFileId
            ? props.previewFileId
            : props.fileId

        const url = await imkit.fetchPresignedUrl({
          bucketName: props.bucketName,
          fileId: targetFileId
        })
        presignedUrl.value = (url as string) || null
      } catch (err) {
        console.error('[LazyMedia] fetchPresignedUrl error:', err)
        presignedUrl.value = null
      }
    }

    onMounted(() => {
      if (!btnRef.value) return

      observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              isInView.value = true
              void fetchPresigned()
              if (observer && entry.target) observer.unobserve(entry.target)
            }
          })
        },
        {
          rootMargin: '50px',
          threshold: 0.01
        }
      )

      observer.observe(btnRef.value)
    })

    onBeforeUnmount(() => {
      if (observer && btnRef.value) observer.unobserve(btnRef.value)
      observer = null
    })

    return () => {
      const attrsCopy = { ...attrs } as Record<string, unknown>
      const className = attrsCopy.class as ClassValue
      delete (attrsCopy as any).class

      const baseClass =
        'group relative aspect-square cursor-pointer overflow-hidden rounded-md bg-surface-muted transition-opacity hover:opacity-90'

      const children: any[] = []

      // Video without preview: use <video> element to show first frame
      if (props.type === 'video' && !hasVideoPreview() && isInView.value) {
        children.push(
          h('video', {
            src: presignedUrl.value,
            class: cn(
              'w-full h-full object-cover transition-opacity duration-300',
              isLoaded.value ? 'opacity-100' : 'opacity-0'
            ),
            onLoadeddata: () => (isLoaded.value = true),
            muted: true,
            playsInline: true,
            preload: 'metadata'
          })
        )
      } else if (isInView.value) {
        children.push(
          h('img', {
            src: presignedUrl.value,
            class: cn(
              'w-full h-full object-cover transition-opacity duration-300',
              isLoaded.value ? 'opacity-100' : 'opacity-0'
            ),
            onLoad: () => (isLoaded.value = true),
            loading: 'lazy'
          })
        )

        if (!isLoaded.value) {
          children.push(
            h(
              'div',
              { class: 'absolute inset-0 flex items-center justify-center' },
              [
                h('div', {
                  class:
                    'h-8 w-8 animate-spin rounded-full border-2 border-accent-vivid border-t-transparent'
                })
              ]
            )
          )
        }
      } else {
        children.push(
          h(
            'div',
            {
              class:
                'absolute inset-0 flex items-center justify-center bg-surface-muted'
            },
            [
              h('div', {
                class:
                  'h-8 w-8 animate-spin rounded-full border-2 border-content-faint border-t-transparent'
              })
            ]
          )
        )
      }

      if (props.type === 'video' && isLoaded.value) {
        children.push(
          h(
            'div',
            { class: 'absolute inset-0 flex items-center justify-center' },
            [
              // 32px, not the 48px this used to be. Both call sites render
              // LazyMedia in the same shape — a `grid-cols-3 gap-2` inside the
              // 350px room-info/content panel, whose `px-4` leaves 318px, so a
              // tile is (318 - 16) / 3 ≈ 100px. At 48px the badge covered 48%
              // of the thumbnail and read as the subject of the tile rather
              // than a control sitting on it; 32px puts it at ~32%.
              //
              // The glyph stays at half the badge, and its optical offset
              // drops with it: a triangle's visual centre sits right of its
              // bounding box, and the 2px of correction that suited a 24px
              // glyph is itself visibly off-centre on a 16px one.
              h(
                'div',
                {
                  class:
                    'flex h-8 w-8 items-center justify-center rounded-full bg-black/60 backdrop-blur-sm'
                },
                [h(Play, { class: 'h-4 w-4 text-white fill-white ml-px' })]
              )
            ]
          )
        )
      }

      if (isLoaded.value) {
        children.push(
          h(
            'div',
            {
              class:
                'absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center p-2'
            },
            [
              props.sender
                ? h(
                    'p',
                    { class: 'text-xs font-medium text-white' },
                    props.sender
                  )
                : null,
              // Both lines are omitted when the caller has nothing to put in
              // them. `date` defaults to '', and dayjs('') is an Invalid Date,
              // so the unguarded version rendered the literal string
              // "Invalid Date" over the thumbnail for any caller that did not
              // pass one.
              dayjs(props.date).isValid()
                ? h(
                    'p',
                    { class: 'text-xs text-white/80' },
                    dayjs(props.date).format('YYYY/MM/DD HH:mm:ss')
                  )
                : null
            ]
          )
        )
      }

      return h(
        'button',
        {
          type: 'button',
          ref: btnRef,
          onClick: props.onClick as any,
          class: cn(baseClass, className, props.class as ClassValue),
          ...(attrsCopy as any)
        },
        children
      )
    }
  }
})
