<script setup lang="ts">
import { computed, ref } from 'vue'
import { useVfm } from 'vue-final-modal'
import Message from '../classes/message'
import { useImkitStore } from '../stores/imkit'
import ConfirmDialogShell from './ConfirmDialogShell.vue'

const vfm = useVfm()
const imkit = useImkitStore()
const isLoading = ref(false)
const errorMessage = ref('')

const props = defineProps<{
  messageId: string
  deleteType: 'everyone' | 'me'
}>()

const message = computed((): Message | undefined =>
  imkit.messageMultiLists
    .get(imkit.selectedRoomId)
    ?.main?.map.get(props.messageId)
)

const confirm = async () => {
  isLoading.value = true
  errorMessage.value = ''
  try {
    if (!message.value) return
    if (props.deleteType === 'everyone') {
      await imkit.deleteMessage({
        roomId: message.value.roomId,
        messageId: props.messageId
      })
    } else {
      await imkit.hideMessage({
        roomId: message.value.roomId,
        messageIds: [props.messageId]
      })
    }
    vfm.closeAll()
  } catch (error) {
    console.error('Error deleting message:', error)
    errorMessage.value = 'deleteMessageFailed'
  } finally {
    isLoading.value = false
  }
}
</script>

<template>
  <ConfirmDialogShell
    :title="$t('confirmDeleteMessage')"
    :cancel-label="$t('cancel')"
    :confirm-label="$t('delete')"
    confirm-test-id="delete-confirm-ok"
    :loading="isLoading"
    @cancel="vfm.closeAll()"
    @confirm="confirm()"
  >
    <template v-if="props.deleteType === 'everyone'">
      {{ $t('deleteForEveryoneWarning') }}
    </template>
    <template v-else>
      {{ $t('deleteForMeWarning') }}
    </template>

    <template #extra>
      <div v-if="errorMessage" role="alert" class="text-base text-danger-vivid">
        {{ $t(errorMessage) }}
      </div>
    </template>
  </ConfirmDialogShell>
</template>
