<script setup lang="ts">
import {
  Ban,
  ChevronLeft,
  Folder as FolderIcon,
  LogOut,
  MoreHorizontal,
  Pin,
  PinOff,
  Plus,
  Search,
  ShieldCheck,
  UserMinus,
  Volume2,
  VolumeX,
  X
} from 'lucide-vue-next'
import { computed, ref, watch } from 'vue'
import type ChatRoomContent from '../classes/chatRoomContent'
import { useImkitModal as useModal } from '../composables/useImkitModal'
import { useRoomContentMediaNavigation } from '../composables/useRoomContentMediaNavigation'
import { getConfig } from '../runtime/config'
import { getUid } from '../runtime/uid'
import { useImkitStore } from '../stores/imkit'
import { getChatRoomContentFileExtension } from '../utils/chatRoomContent'
import { getFileIcon } from '../utils/fileIcon'
import { deriveTagPalette } from '../utils/tagColor'
import { RoomType } from './../classes/room'
import AddToFolderModal from './AddToFolderModal.vue'
import AvatarView from './AvatarView.vue'
import BlockUserConfirmModal from './BlockUserConfirmModal.vue'
import HeaderDivider from './HeaderDivider.vue'
import LeaveGroupConfirmModal from './LeaveGroupConfirmModal.vue'
import MenuItemContent from './MenuItemContent.vue'
import MoveOutConfirmModal from './MoveOutConfirmModal.vue'
import TagsModal from './TagsModal.vue'
import LazyMedia from './tribo/ui/lazy-media'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger
} from './tribo/ui/dropdown-menu'
import ContentLightboxDialog from './ui/ContentLightboxDialog.vue'

const imkit = useImkitStore()
const config = getConfig()
const room = computed(() => imkit.rooms[imkit.selectedRoomId])
const users = computed(() => imkit.users)
const uid = computed(() => getUid())
const settings = computed(() => config.settings)
const roomContentEnabled = computed(
  () => settings.value.roomContentEnabled !== false
)
const showCustomRoomInfoIframe = computed(() => {
  return config.settings.customRoomInfoIframeURL
})
const customRoomInfoIframeURL = computed(() => {
  const base = config.settings.customRoomInfoIframeURL
  if (!base) return ''
  const url = new URL(base, window.location.href)
  url.searchParams.set('roomId', String(imkit.selectedRoomId))
  return url.toString()
})
const blockedUsers = computed(() => imkit.blockedUsers)

const canMoveOut = computed(() => {
  return room.value.type === 'group'
})
const back = () => {
  imkit.$patch({ isRoomInfoVisible: false })
}
// --- Block / unblock.
//
// Both entry points — the direct-room quick action and the group member
// row's `⋯` menu — route through these two functions, so the confirmation
// rule and the failure handling cannot drift between them.
//
// These were fire-and-forget (`imkit.blockUser({...})`, no await, no catch).
// The store action awaits the POST and only THEN commits to state, so a
// rejection left the panel unchanged, showed nothing, and escaped as an
// unhandled rejection — the user believed they had blocked someone and had
// not. Now the flag is flipped optimistically so the control responds at
// once (that flip is the only success feedback this codebase can give: there
// is no toast/snackbar surface, and adding a global one would touch public
// API), and a failure puts the flag back and raises the confirm modal's own
// error branch.
const openBlockErrorDialog = (uid: string) => {
  const { open } = useModal({
    component: BlockUserConfirmModal,
    attrs: { roomId: room.value.id, uid, mode: 'error' as const }
  })
  open()
}

// Blocking is confirmed; unblocking is not. Unblocking is the correction
// path for a mistaken block, so a dialog in front of it would make the
// mistake harder to undo than to make.
const blockUser = (uid: string) => {
  const { open } = useModal({
    component: BlockUserConfirmModal,
    attrs: { roomId: room.value.id, uid }
  })
  open()
}

const unblockUser = async (uid: string) => {
  const wasBlocked = imkit.blockedUsers[uid]
  delete imkit.blockedUsers[uid]
  try {
    await imkit.unblockUser({ roomId: room.value.id, uid })
  } catch (error) {
    console.error('Failed to unblock user:', error)
    if (wasBlocked) {
      imkit.blockedUsers[uid] = wasBlocked
    }
    openBlockErrorDialog(uid)
  }
}

// The one other person in a direct room. Used by the block quick action,
// which replaces the member row that a direct room no longer renders.
const directCounterpartId = computed(() => {
  if (room.value.type !== RoomType.Direct) return ''
  return room.value.memberIds.find((id: string) => id !== uid.value) ?? ''
})
const isDirect = computed(() => room.value.type === RoomType.Direct)
const isCounterpartBlocked = computed(
  () => !!blockedUsers.value[directCounterpartId.value]
)
const toggleBlock = () => {
  const target = directCounterpartId.value
  if (!target) return
  if (isCounterpartBlocked.value) {
    unblockUser(target)
  } else {
    blockUser(target)
  }
}
const isRequesting = computed(
  () => !!imkit.isRequesting[`/blockStatus/room/${room.value.id}`]
)

const confirmMoveOut = (memberId: string) => {
  const { open } = useModal({
    component: MoveOutConfirmModal,
    attrs: {
      memberIdToMoveOut: memberId,
      roomId: room.value.id
    }
  })

  open()
}

const confirmLeaveGroup = () => {
  const { open } = useModal({
    component: LeaveGroupConfirmModal,
    attrs: { roomId: room.value.id, memberId: uid.value }
  })
  open()
}
const shouldShowBlockControl = (memberId: string) => {
  if (isRequesting.value) {
    return false
  }
  if (memberId === uid.value) {
    return false
  }
  // Currently unreachable: direct rooms no longer render a members section
  // at all, so no member row exists to ask about. Kept rather than folded
  // away so the function still answers its own question correctly if that
  // section ever comes back for direct rooms.
  if (room.value.type === RoomType.Direct) {
    return true
  }
  return room.value.isSuperuser
}

// --- Quick actions: pin, mute, in-room search. `加成員` (add member) from
// the reference has no home here — there is no addMembers/inviteMembers
// action in the store (only `removeMembers`), so it is left out rather than
// built or stubbed. See round8-report.md.
const isSticky = computed(() => room.value.pref?.sticky ?? false)
const toggleSticky = async () => {
  await imkit.updateRoomPrefs({
    roomId: room.value.id,
    prefs: { sticky: !isSticky.value }
  })
}
const toggleMute = () => {
  imkit.toggleNotification(room.value.id)
}
const openInRoomSearch = () => {
  imkit.$patch({
    isRoomInfoVisible: false,
    isSearchInRoomMode: true
  })
}

const PREVIEW_SLOTS = 6
const roomContentMedia = computed<ChatRoomContent[]>(
  () => imkit.chatRoomContentMedia
)
const roomContentFiles = computed<ChatRoomContent[]>(
  () => imkit.chatRoomContentFiles
)
const roomContentTotal = computed(
  () =>
    imkit.chatRoomContentMediaTotalCount + imkit.chatRoomContentFilesTotalCount
)
const roomContentPreview = computed(() => {
  const media = roomContentMedia.value.slice(0, PREVIEW_SLOTS)
  const files = roomContentFiles.value.slice(
    0,
    Math.max(0, PREVIEW_SLOTS - media.length)
  )
  const shown = media.length + files.length
  if (shown === PREVIEW_SLOTS && roomContentTotal.value > PREVIEW_SLOTS) {
    return files.length > 0
      ? { media, files: files.slice(0, -1) }
      : { media: media.slice(0, -1), files }
  }
  return { media, files }
})
const roomContentOverflow = computed(() => {
  const shown =
    roomContentPreview.value.media.length +
    roomContentPreview.value.files.length
  return Math.max(0, roomContentTotal.value - shown)
})

const fetchRoomContentPreview = async (roomId: string) => {
  try {
    await Promise.all([
      imkit.chatRoomContentMediaRoomId === roomId
        ? Promise.resolve()
        : imkit.fetchRoomContentMedia({ roomId }),
      imkit.chatRoomContentFilesRoomId === roomId
        ? Promise.resolve()
        : imkit.fetchRoomContentFiles({ roomId })
    ])
  } catch (error) {
    console.error('[ChatRoomInfo] failed to load room content:', error)
  }
}

watch(
  [() => room.value?.id, roomContentEnabled],
  ([roomId, enabled]) => {
    if (!enabled) {
      imkit.$patch({ isRoomContentVisible: false })
      return
    }
    if (roomId) void fetchRoomContentPreview(roomId)
  },
  { immediate: true }
)

const openRoomContent = () => {
  if (!roomContentEnabled.value) return
  imkit.$patch({ isRoomContentVisible: true })
}

const lightboxOpen = ref(false)
const mediaNavigation = useRoomContentMediaNavigation(() => room.value?.id)
const lightboxMedia = mediaNavigation.selectedMedia
const openMediaLightbox = (index: number) => {
  mediaNavigation.selectMedia(roomContentMedia.value[index] ?? null)
  lightboxOpen.value = true
}
const previousMedia = mediaNavigation.previousMedia
const nextMedia = mediaNavigation.nextMedia

// --- Organize: tags + folder. Both reuse the same modals RoomCell.vue's
// action menu already opens, just triggered from this panel instead.
const roomTags = computed(() => room.value.pref?.tags ?? [])
const roomTagColors = computed(() => room.value.pref?.tagColors ?? {})
const tagChipStyle = (tagHex: string) => {
  const palette = deriveTagPalette(tagHex)
  return {
    '--tag-bg': palette.lightBg,
    '--tag-fg': palette.lightFg,
    '--tag-bg-dark': palette.darkBg,
    '--tag-fg-dark': palette.darkFg
  }
}
const openTagsModal = () => {
  const { open } = useModal({
    component: TagsModal,
    attrs: { roomId: room.value.id }
  })
  open()
}

// A room lives in at most one folder client-side, and there is no reverse
// index from roomId -> folderId (mirrors AddToFolderModal.vue's own
// currentFolderId computed).
const currentFolder = computed(() => {
  for (const id of imkit.sortedFolderIds) {
    const folder = imkit.folders[id]
    if (folder && folder.roomIds.includes(room.value.id)) {
      return folder
    }
  }
  return null
})
const openFolderModal = () => {
  const { open } = useModal({
    component: AddToFolderModal,
    attrs: { roomId: room.value.id }
  })
  open()
}
</script>

<template>
  <div
    class="absolute inset-0 flex w-full flex-col bg-surface sm:relative sm:w-[350px] sm:max-w-[350px] sm:min-w-[350px]"
  >
    <div
      data-testid="room-info-header"
      class="relative flex h-(--imkit-header-height) items-center gap-3 px-4"
    >
      <!-- Overlaid border, not a real `border-b` — see HeaderDivider.vue. -->
      <HeaderDivider />
      <ChevronLeft
        :size="24"
        class="cursor-pointer text-content-muted sm:hidden"
        @click="back"
      />
      <div class="flex-1 text-base font-semibold text-content">
        {{ $t('roomInfo') }}
      </div>
      <button
        type="button"
        data-testid="room-info-close"
        class="hidden cursor-pointer items-center justify-center rounded-full p-1 text-content-muted hover:bg-surface-hover sm:flex"
        :aria-label="$t('close')"
        @click="back"
      >
        <X :size="20" />
      </button>
    </div>

    <div class="flex min-h-0 flex-1 flex-col overflow-auto pb-3">
      <!-- idblock -->
      <!--
        `pt-6`, not `pt-2`. This block sits directly under the panel header's
        overlaid rule, so 8px left the avatar almost against a hard boundary —
        an inside-a-component value where a between-groups one belongs (see
        CLAUDE.md's spacing note). 24px reads as the identity block starting,
        rather than as the header having thick bottom padding.
      -->
      <div
        class="flex flex-col items-center gap-2 px-4 pt-6 pb-3.5 text-center"
      >
        <!--
          72px maps the reference's `.idblock .avatar` (72px). The camera
          edit badge is skipped: there is no room-avatar-upload action in
          the store, and the reference's editable room name (`h4`) is also
          plain text here for the same reason — no room-rename action
          exists. See round8-report.md.
        -->
        <!-- Cover when set, group glyph as the fallback — see the note on
             the same expression in RoomCell.vue for why a group uses
             `coverUrl` rather than `avatars[0]`. -->
        <avatar-view
          :url="room.isGroup ? room.coverUrl : room.avatars[0].url"
          :name="room.isGroup ? (room.displayName ?? '') : room.avatars[0].name"
          :is-group="room.isGroup"
          class="h-18 w-18 text-xl"
        />
        <h4 class="text-xl font-bold text-content">{{ room.displayName }}</h4>
      </div>

      <!-- qa: quick actions -->
      <div class="flex justify-center gap-2.5 px-4 pb-4">
        <button
          type="button"
          data-testid="room-info-pin"
          class="flex w-15 cursor-pointer flex-col items-center gap-1.5 text-xs text-content"
          @click="toggleSticky"
        >
          <span
            class="flex h-11 w-11 items-center justify-center rounded-full"
            :class="
              isSticky
                ? 'bg-accent text-white'
                : 'bg-surface-muted text-accent hover:bg-accent-subtle'
            "
          >
            <component :is="isSticky ? PinOff : Pin" :size="20" />
          </span>
          {{ isSticky ? $t('unpin') : $t('pin') }}
        </button>
        <!--
          Mute is a TOGGLE, so its pill carries the same engaged fill as pin
          above and block below (`bg-accent` + white glyph when on, the
          `surface-muted` resting pill when off). It used to be the only
          toggle in this row without one: the pill stayed byte-identical in
          both states and the entire on/off signal rested on the glyph
          swapping Volume2 <-> VolumeX and the label swapping mute <->
          unmute. Two small, easily-missed channels — sitting directly
          beside a pinned row that DOES fill — is what made this read as
          having no switch to it.

          Search, the remaining button in this row, deliberately keeps the
          unconditional resting pill: it opens in-room search rather than
          holding an on/off state, so an engaged fill would be claiming a
          state it does not have.
        -->
        <button
          type="button"
          data-testid="room-info-mute"
          class="flex w-15 cursor-pointer flex-col items-center gap-1.5 text-xs text-content"
          @click="toggleMute"
        >
          <span
            class="flex h-11 w-11 items-center justify-center rounded-full"
            :class="
              room.muted
                ? 'bg-accent text-white'
                : 'bg-surface-muted text-accent hover:bg-accent-subtle'
            "
          >
            <component :is="room.muted ? VolumeX : Volume2" :size="20" />
          </span>
          {{ room.muted ? $t('unmute') : $t('mute') }}
        </button>
        <!--
          Direct rooms only, and it sits between mute and search so the row
          reads 置頂 / 靜音 / 封鎖 / 搜尋. This is the direct-room entry point
          for block: a direct room no longer renders a members section, so
          the member row's `⋯` menu that used to carry it is gone. Group
          rooms keep block in that menu, superuser-gated — both routes call
          the same toggleBlock/blockUser/unblockUser pair.

          A toggle like mute: the icon and label follow the current state.
        -->
        <!--
          `!isRequesting` for the same reason the member-row block control
          carried it: while GET /blockStatus/room/{id} is in flight the
          blocked-set is not yet known, so the toggle would render a guessed
          label and act on a state we have not confirmed.
        -->
        <button
          v-if="isDirect && directCounterpartId && !isRequesting"
          type="button"
          data-testid="room-info-block"
          class="flex w-15 cursor-pointer flex-col items-center gap-1.5 text-xs text-content"
          @click="toggleBlock"
        >
          <span
            class="flex h-11 w-11 items-center justify-center rounded-full"
            :class="
              isCounterpartBlocked
                ? 'bg-accent text-white'
                : 'bg-surface-muted text-accent hover:bg-accent-subtle'
            "
          >
            <component
              :is="isCounterpartBlocked ? ShieldCheck : Ban"
              :size="20"
            />
          </span>
          {{ isCounterpartBlocked ? $t('unblock') : $t('block') }}
        </button>
        <button
          type="button"
          data-testid="room-info-search"
          class="flex w-15 cursor-pointer flex-col items-center gap-1.5 text-xs text-content"
          @click="openInRoomSearch"
        >
          <span
            class="flex h-11 w-11 items-center justify-center rounded-full bg-surface-muted text-accent hover:bg-accent-subtle"
          >
            <Search :size="20" />
          </span>
          {{ $t('search') }}
        </button>
      </div>

      <div
        v-if="roomContentEnabled && roomContentTotal > 0"
        data-testid="room-content-section"
        class="border-t border-border py-4"
      >
        <h5 class="mx-4 mb-2 flex items-center justify-between gap-2">
          <span
            class="text-xs font-bold tracking-wider text-content-subtle uppercase"
          >
            {{ $t('chatRoomContent') }}({{ roomContentTotal }})
          </span>
          <button
            type="button"
            data-testid="room-info-content-all"
            class="cursor-pointer text-xs font-semibold text-accent-vivid hover:underline"
            @click="openRoomContent"
          >
            {{ $t('all') }}
          </button>
        </h5>
        <div class="grid grid-cols-3 gap-2 px-4">
          <LazyMedia
            v-for="(item, index) in roomContentPreview.media"
            :key="item._id"
            :bucket-name="item.room"
            :file-id="item._id"
            :preview-file-id="item.preview?._id"
            :alt="item.client?.nickname"
            :type="item.fileType"
            :sender="item.client?.nickname"
            :date="item.createdAt"
            class="aspect-square w-full"
            :on-click="() => openMediaLightbox(index)"
          />
          <button
            v-for="file in roomContentPreview.files"
            :key="file._id"
            type="button"
            class="flex aspect-square w-full cursor-pointer flex-col items-center justify-center gap-1 rounded-md bg-surface-muted transition-colors hover:bg-surface-hover"
            @click="openRoomContent"
          >
            <component
              :is="getFileIcon(getChatRoomContentFileExtension(file))"
              :size="20"
              class="text-accent-vivid"
            />
            <span
              class="max-w-full truncate px-1 text-xs font-semibold text-content-subtle uppercase"
            >
              {{ getChatRoomContentFileExtension(file) }}
            </span>
          </button>
          <button
            v-if="roomContentOverflow > 0"
            type="button"
            data-testid="room-info-content-overflow"
            class="flex aspect-square w-full cursor-pointer items-center justify-center rounded-md bg-surface-muted text-base font-semibold text-accent-vivid transition-colors hover:bg-surface-hover"
            @click="openRoomContent"
          >
            +{{ roomContentOverflow }}
          </button>
        </div>
      </div>

      <!--
        The 8px band between sections is a deliberate device (CLAUDE.md /
        round8-room-settings.md) — a thick `surface-muted` divider, not a
        1px border, so the panel reads as grouped cards without any card
        element existing.
      -->

      <!--
        sect: tags — split into its own section (was one row shared with
        folder, under a single `organize` heading, itself with a "標籤"
        label — a duplicated label, since the row's own label was ALSO
        "標籤"; that locale key is now deleted from all 12 files rather
        than left as litter). The heading now carries the name and count
        (`標籤(12)`, matching the `成員(2)` convention this panel already
        uses for its members heading, rather than the reference mockup's
        `標籤 12`, so the two headings agree), a `管理標籤` action opens the
        same tags modal the old row's click did, and there is no longer an
        icon + right-aligned-value row underneath: the chips themselves ARE
        the body, wrapping onto as many lines as a room's tag count needs —
        the whole point of this split, since a room can carry well over
        five.
      -->
      <div class="border-t border-border py-4">
        <h5 class="mx-4 mb-2 flex items-center justify-between gap-2">
          <span
            class="text-xs font-bold tracking-wider text-content-subtle uppercase"
          >
            {{ $t('tag') }}({{ roomTags.length }})
          </span>
          <button
            type="button"
            data-testid="room-info-tags-manage"
            class="cursor-pointer text-xs font-semibold text-accent-vivid hover:underline"
            @click="openTagsModal"
          >
            {{ $t('manageTag') }}
          </button>
        </h5>
        <div class="flex flex-wrap gap-2 px-4">
          <!--
            `inline-flex items-center`, not a bare inline `<span>`. An inline
            element's background box is drawn around the font's content area and
            positioned by the BASELINE, so padding does not centre the text in
            it — and CJK, which has no descenders, then sits visibly high in the
            space the descender reserves. The room-row chip is a block `<div>`
            and never had this; the picker chip is already `flex items-center`.

            `leading-none` on top of that, because `inline-flex` alone did not
            finish the job: measured in the running panel the label still sat
            0.8px high (6.00 above, 6.80 below). The flex item's line box is
            16.8px against a 14px glyph box, and the baseline positioning
            inside it is what carries the asymmetry. Collapsing the line box to
            the font size lets flex centre the glyphs directly — measured 6.40
            / 6.40, with the chip's height unchanged at 26.8px either way, so
            this costs no layout shift.
          -->
          <span
            v-for="tg in roomTags"
            :key="tg"
            class="tag-chip inline-flex items-center rounded-full px-3 py-1 text-xs leading-none font-semibold"
            :style="tagChipStyle(roomTagColors[tg])"
          >
            {{ tg }}
          </span>
          <!--
            A soft FILL with no outline, like the twelve chips beside it —
            not the dashed `border-border-strong` outline this first
            shipped with. Both tokens there were real, so this was never a
            migration miss; `border-strong` is simply the wrong ROLE here.
            It is the interactive-outline token, pitched at 3:1 against its
            grounds (see src/style.css), so against a row of pastel fills
            with no hard edge the add-chip read as the heaviest, darkest
            thing in the flow — a different design language, when it should
            be the lightest. `surface-muted` + `content-subtle` puts it in
            the chip family and at the bottom of its emphasis order;
            `content-subtle` also clears the 4.5:1 text floor on
            `surface-muted` across supported palettes and colour modes. The
            `+` glyph carries the add
            affordance the dashes were doing.
          -->
          <button
            type="button"
            data-testid="room-info-tags-add"
            class="flex cursor-pointer items-center gap-1 rounded-full border border-dashed border-border px-3 py-1 text-xs font-semibold text-content-subtle hover:border-border-strong hover:text-content"
            @click="openTagsModal"
          >
            <Plus :size="12" />
            {{ $t('add') }}
          </button>
        </div>
      </div>

      <!-- sect: folder — its own single-row section; it holds exactly one
           value, so it keeps the `value ›` shape rather than wrapping. -->
      <div class="border-t border-border py-4">
        <h5
          class="mx-4 mb-2 flex items-center text-xs font-bold tracking-wider text-content-subtle uppercase"
        >
          {{ $t('roomPrefFolder') }}
        </h5>
        <button
          type="button"
          data-testid="room-info-folder"
          class="flex min-h-11 w-full cursor-pointer items-center gap-3 px-4 py-2.5 text-left hover:bg-surface-hover"
          @click="openFolderModal"
        >
          <span
            class="flex h-7.5 w-7.5 flex-none items-center justify-center rounded-md bg-surface-muted text-accent"
          >
            <FolderIcon :size="16" />
          </span>
          <span class="flex-1 truncate text-base text-content">{{
            currentFolder ? currentFolder.name : $t('unclassified')
          }}</span>
          <!--
            Same treatment as the tags section's 管理標籤: both open a dialog,
            so they are one class of action and were styled as two. The chevron
            goes with the grey — it reads as navigation to another screen, which
            is not what either of these does.
          -->
          <span class="text-xs font-semibold text-accent-vivid">
            {{ $t('changeFolder') }}
          </span>
        </button>
      </div>

      <!--
        sect: members — group rooms only. In a direct room the list would be
        you plus the one person whose name is already the panel title, so it
        restates the title and nothing else. Dropping it also removes the
        member row's `⋯` menu, which is why block is promoted to a quick
        action above for direct rooms.
      -->
      <div v-if="!isDirect" class="border-t border-border py-4">
        <!--
          The reference's `管理成員` (manage members) header link opens a
          separate full members page that does not exist in this SDK, so
          the link is omitted rather than left dangling — matching the
          spec's "omit the link and say so" guidance.
        -->
        <!--
          `成員(2)`, not `2 名成員`. The prose form is already the description
          line under the room avatar; repeating it here made the same sentence
          appear twice in one panel. A section heading wants the label with its
          count, so this composes `members` + the number rather than reusing
          `memberCount`, which keeps all 12 locales working without a new key.
        -->
        <h5
          class="mx-4 mb-2 flex items-center text-xs font-bold tracking-wider text-content-subtle uppercase"
        >
          {{ $t('members') }}({{ room.memberIds.length }})
        </h5>
        <!--
          Not clickable — no click handler on the row itself, only its "..."
          button is. A hover fill here would invite a click that does
          nothing, so this loses the hover half of the cursor/hover rule
          (see HeaderDivider.vue's neighbours in this file for the other
          half: clickable rows/buttons keep `cursor-pointer` explicitly,
          since Tailwind 4 preflight doesn't give `<button>` one).
        -->
        <div
          v-for="memberId in room.memberIds"
          :key="memberId"
          class="flex min-h-13 items-center gap-2.5 px-4 py-2.5"
        >
          <avatar-view
            :url="users[memberId]?.avatarUrl ?? ''"
            :name="users[memberId]?.nickname"
            class="h-[38px] w-[38px] text-xs"
          />
          <div class="flex min-w-0 flex-1 flex-col overflow-hidden">
            <span class="truncate text-base font-semibold text-content">{{
              users[memberId]?.nickname
            }}</span>
            <span
              v-if="users[memberId]?.city && users[memberId]?.country"
              class="truncate text-xs text-content-subtle"
            >
              {{ users[memberId]?.city }}, {{ users[memberId]?.country }}
            </span>
          </div>
          <template
            v-if="
              settings.showMemberActionMenu &&
              (shouldShowBlockControl(memberId) ||
                (canMoveOut && memberId !== uid))
            "
          >
            <DropdownMenu :modal="false">
              <DropdownMenuTrigger as-child>
                <button
                  type="button"
                  :data-testid="`member-actions-${memberId}`"
                  :aria-label="$t('more')"
                  class="ml-auto flex h-9 w-9 cursor-pointer items-center justify-center rounded-md text-content-muted hover:bg-surface"
                >
                  <MoreHorizontal :size="18" />
                </button>
              </DropdownMenuTrigger>
              <!--
                All three rows go through `MenuItemContent`, like every
                other action menu in the app — they were bare labels, the
                only menu in the app without glyphs. Hand-adding an icon
                here would re-introduce exactly the divergence that
                component exists to make unrepresentable: the glyph's
                colour has to track the item's danger state, and a glyph
                with its own colour class beats the row's inherited one,
                which is how a grey icon beside a red label shipped three
                times (see MenuItemContent.vue's own note).

                Icons are member-scoped, not message-scoped: `UserMinus`
                for removing a member from the group (NOT `Trash2`, which
                means destroy-the-thing and is what the room-list menu uses
                for deleting a room), and the `Ban`/`ShieldCheck` pair for
                block/unblock.
              -->
              <DropdownMenuContent align="end" side="bottom">
                <DropdownMenuItem
                  v-if="canMoveOut && memberId !== uid"
                  @select="confirmMoveOut(memberId)"
                >
                  <MenuItemContent :icon="UserMinus" :label="$t('moveOut')" />
                </DropdownMenuItem>
                <template v-if="shouldShowBlockControl(memberId)">
                  <DropdownMenuItem
                    v-if="blockedUsers[memberId]"
                    @select="unblockUser(memberId)"
                  >
                    <MenuItemContent
                      :icon="ShieldCheck"
                      :label="$t('unblock')"
                    />
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    v-else
                    class="text-danger-vivid focus:text-danger-vivid"
                    @select="blockUser(memberId)"
                  >
                    <MenuItemContent
                      :icon="Ban"
                      :label="$t('block')"
                      :danger="true"
                    />
                  </DropdownMenuItem>
                </template>
              </DropdownMenuContent>
            </DropdownMenu>
          </template>
        </div>
        <!--
          `＋ 新增成員` (add member) from the reference is skipped: no
          addMembers/inviteMembers action exists in the store. See
          round8-report.md.
        -->
      </div>

      <!-- sect danger -->
      <div
        v-if="room.isGroup && settings.showLeaveRoomButton"
        class="border-t border-border py-4"
      >
        <!--
          `刪除頻道` (delete channel) from the reference is skipped this
          round: the panel previously exposed no delete/hide-room capability
          at all, so adding one now is new capability for this component,
          not a restyle — even though the store has `deleteRoom` /
          `updateRoomPrefs({ hidden: true })` wired elsewhere (RoomCell.vue's
          DeleteRoomModal.vue, which this round does not own or modify).
          See round8-report.md.
        -->
        <h5
          class="mx-4 mb-2 flex items-center text-xs font-bold tracking-wider text-danger-vivid uppercase"
        >
          {{ $t('dangerZone') }}
        </h5>
        <button
          type="button"
          data-testid="leave-group-button"
          class="flex min-h-11 w-full cursor-pointer items-center gap-3 px-4 py-2.5 text-left hover:bg-surface-hover"
          @click="confirmLeaveGroup"
        >
          <span
            class="flex h-7.5 w-7.5 flex-none items-center justify-center rounded-md bg-surface-muted text-danger-vivid"
          >
            <LogOut :size="16" />
          </span>
          <span class="text-base text-danger-vivid">{{
            $t('leaveGroup')
          }}</span>
        </button>
      </div>

      <iframe
        v-if="showCustomRoomInfoIframe"
        :src="customRoomInfoIframeURL"
        sandbox="allow-scripts allow-same-origin"
        frameborder="0"
      />
    </div>
    <ContentLightboxDialog
      v-if="roomContentEnabled"
      :open="lightboxOpen"
      :selected-media="lightboxMedia"
      :previous-media="previousMedia"
      :next-media="nextMedia"
      :media-count="mediaNavigation.mediaCount.value"
      :can-navigate-previous="mediaNavigation.canNavigatePrevious.value"
      :can-navigate-next="mediaNavigation.canNavigateNext.value"
      :room-id="room.id"
      :sender-name="lightboxMedia?.client?.nickname"
      :created-at="lightboxMedia?.createdAt"
      @close="lightboxOpen = false"
    />
  </div>
</template>

