export default class Folder {
  id: string
  name: string
  roomIds: string[]

  constructor(id: string, name: string, roomIds: string[]) {
    this.id = id
    this.name = name
    this.roomIds = roomIds
  }

  get payload(): Record<string, unknown> {
    return {
      children: this.roomIds.map((roomId) => ({
        id: roomId,
        type: 'room'
      }))
    }
  }
}
