<script lang="ts">
import axios from 'axios'
import { LocateFixed, X } from 'lucide-vue-next'
import { throttle } from 'throttle-debounce'
import type { ComponentOptions } from 'vue'
import { computed, defineComponent, ref } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import { useI18n } from 'vue-i18n'
import { AdvancedMarker, GoogleMap } from 'vue3-google-map'
import { GOOGLE_MAP_DEMO_MAP_ID } from '../constants'
import { getConfig } from '../runtime/config'
import { useImkitStore } from '../stores/imkit'
import CloseSvg from './svgs/CloseSvg.vue'

enum LocationSource {
  Map,
  CurrentPosition
}

class Location {
  lat: number
  lng: number
  address: string | null

  constructor(lat: number, lng: number, address: string | null = null) {
    this.lat = lat
    this.lng = lng
    this.address = address
  }

  get isValid(): boolean {
    return this.address !== null
  }
}

const LocationModalComponent = defineComponent({
  components: {
    GoogleMap,
    AdvancedMarker,
    CloseSvg,
    VueFinalModal,
    LocateFixed,
    X
  },
  setup() {
    const vfm = useVfm()
    const { t } = useI18n()
    const imkit = useImkitStore()
    const config = getConfig()
    const apiKey = config.mapApiKey
    const mapId = config.mapId || GOOGLE_MAP_DEMO_MAP_ID
    const mapRef = ref()
    const location = ref<Location>(new Location(21.30895, -157.826182))
    const center = ref({ lat: location.value.lat, lng: location.value.lng })
    const markerOptions = computed(() => ({
      position: {
        lat: location.value.lat,
        lng: location.value.lng
      }
    }))
    const address = ref('')
    const isGettingCurrentPosition = ref(false)
    const zoom = ref(10)
    const isRequesting = ref(false)
    const geolocationPositionErrorMessage = ref('')

    const fetchCurrentPosition = (): Promise<{ lat: number; lng: number }> => {
      return new Promise((resolve, reject) => {
        isGettingCurrentPosition.value = true
        navigator.geolocation.getCurrentPosition(
          (pos) => {
            let { latitude, longitude } = pos.coords
            geolocationPositionErrorMessage.value = ''
            isGettingCurrentPosition.value = false
            resolve({ lat: latitude, lng: longitude })
          },
          (error) => {
            isGettingCurrentPosition.value = false
            switch (error.code) {
              case error.PERMISSION_DENIED:
                geolocationPositionErrorMessage.value = t(
                  'noAccessLocationPermission'
                )
                break
              case error.POSITION_UNAVAILABLE:
                geolocationPositionErrorMessage.value = t(
                  'locationInfoUnavailable'
                )
                break
              case error.TIMEOUT:
                geolocationPositionErrorMessage.value = t(
                  'requestLocationTimeout'
                )
                break
              default:
                break
            }
            reject(error)
          },
          {
            enableHighAccuracy: true,
            timeout: 10000,
            maximumAge: 0
          }
        )
      })
    }

    const getStreetAddressFrom = async (lat: number, lng: number) => {
      try {
        const { data } = await axios.get(
          `https://maps.googleapis.com/maps/api/geocode/json?latlng=${lat},${lng}&key=${apiKey}`
        )
        if (data.error_message) {
          throw new Error(data.error_message)
        } else {
          return data.results[0].formatted_address
        }
      } catch (error) {
        geolocationPositionErrorMessage.value = t('addressUnavailable')
        throw error
      }
    }

    const debounceLocationChange = throttle(
      700,
      async (source: LocationSource) => {
        try {
          if (source === LocationSource.Map) {
            const center = mapRef.value?.map.getCenter()
            if (center) {
              const { lat, lng } = center
              location.value = new Location(lat(), lng())
            }
          } else if (source === LocationSource.CurrentPosition) {
            const { lat, lng } = await fetchCurrentPosition()
            location.value = new Location(lat, lng)
            zoom.value = 17
            mapRef.value?.map.panTo({ lat, lng })
          }
          let { lat, lng } = location.value
          lng = ((((lng + 180) % 360) + 360) % 360) - 180
          lat = Math.max(Math.min(lat, 90), -90)
          address.value = await getStreetAddressFrom(lat, lng)
          location.value = new Location(lat, lng, address.value)
        } catch (error) {
          console.error(error)
        }
      },
      { noLeading: false, noTrailing: false }
    )

    const send = async () => {
      isRequesting.value = true
      const payload = {
        roomId: imkit.selectedRoomId,
        messageType: 'location',
        message: address.value,
        latitude: markerOptions.value.position.lat,
        longitude: markerOptions.value.position.lng
      }
      vfm.closeAll()
      await imkit.sendMessage(payload)
      isRequesting.value = false
    }

    debounceLocationChange(LocationSource.CurrentPosition)

    return {
      vfm,
      t,
      apiKey,
      mapId,
      mapRef,
      location,
      center,
      markerOptions,
      address,
      isGettingCurrentPosition,
      zoom,
      isRequesting,
      geolocationPositionErrorMessage,
      debounceLocationChange,
      LocationSource,
      send
    }
  }
}) as ComponentOptions

export default LocationModalComponent
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="flex flex-col bg-surface rounded-xl border border-border overflow-hidden sm:w-[450px] w-[350px] shadow-raised"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div class="relative flex justify-center">
      <google-map
        ref="mapRef"
        :api-key="apiKey"
        :center="center"
        :zoom="zoom"
        :disable-default-ui="true"
        :map-id="mapId"
        class="h-[250px] w-[350px] sm:h-[350px] sm:w-[450px]"
        @center_changed="debounceLocationChange(LocationSource.Map)"
      >
        <AdvancedMarker :options="markerOptions" />
      </google-map>
      <button
        class="absolute top-2 right-2 flex items-center justify-center rounded-full shadow-raised"
        @click="vfm.closeAll()"
      >
        <CloseSvg class="h-9 w-9" />
      </button>
      <button
        class="absolute right-2 bottom-2 flex h-9 w-9 items-center justify-center rounded-full bg-surface shadow-raised"
        @click="debounceLocationChange(LocationSource.CurrentPosition)"
      >
        <LocateFixed
          :size="20"
          class="text-content-muted"
          :class="{ 'animate-pulse': isGettingCurrentPosition }"
        />
      </button>
      <Transition>
        <!--
          `bottom-12`, not `bottom-2`. At bottom-2 this sat directly on top
          of Google's attribution strip ("Map data ©2026 Google / Terms /
          Report a map error"), covering its upper half — that strip is
          required to stay visible under the Maps Platform terms, so this is
          a licensing constraint and not only a visual one. 48px also clears
          the current-position button, which occupies 8-44px from the bottom
          on the same edge.

          Centred explicitly rather than inheriting the parent's
          `justify-center`: an absolutely positioned box is taken out of the
          flex flow, so it was only landing near the middle by way of its
          static position, which is not something to rely on.
        -->
        <div
          v-if="geolocationPositionErrorMessage"
          class="absolute bottom-12 left-1/2 flex max-w-[calc(100%-5rem)] -translate-x-1/2 items-center gap-1 rounded-full border border-border bg-surface p-2 text-xs text-content shadow-raised"
        >
          <X :size="16" class="text-danger-vivid" />
          {{ geolocationPositionErrorMessage }}
        </div>
      </Transition>
    </div>

    <button
      class="m-2 flex flex-col items-center gap-0.5 rounded-md bg-accent p-2 text-white disabled:cursor-not-allowed disabled:bg-accent-subtle disabled:text-accent-vivid"
      :disabled="isGettingCurrentPosition || isRequesting || !location.isValid"
      @click="send"
    >
      <div
        v-if="isRequesting"
        class="flex h-10.5 w-full items-center justify-center"
      >
        <svg
          class="h-6 w-6 animate-spin fill-white text-surface-muted"
          viewBox="0 0 100 101"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M100 50.5908C100 78.2051 77.6142 100.591 50 100.591C22.3858 100.591 0 78.2051 0 50.5908C0 22.9766 22.3858 0.59082 50 0.59082C77.6142 0.59082 100 22.9766 100 50.5908ZM9.08144 50.5908C9.08144 73.1895 27.4013 91.5094 50 91.5094C72.5987 91.5094 90.9186 73.1895 90.9186 50.5908C90.9186 27.9921 72.5987 9.67226 50 9.67226C27.4013 9.67226 9.08144 27.9921 9.08144 50.5908Z"
            fill="currentColor"
          />
          <path
            d="M93.9676 39.0409C96.393 38.4038 97.8624 35.9116 97.0079 33.5539C95.2932 28.8227 92.871 24.3692 89.8167 20.348C85.8452 15.1192 80.8826 10.7238 75.2124 7.41289C69.5422 4.10194 63.2754 1.94025 56.7698 1.05124C51.7666 0.367541 46.6976 0.446843 41.7345 1.27873C39.2613 1.69328 37.813 4.19778 38.4501 6.62326C39.0873 9.04874 41.5694 10.4717 44.0505 10.1071C47.8511 9.54855 51.7191 9.52689 55.5402 10.0491C60.8642 10.7766 65.9928 12.5457 70.6331 15.2552C75.2735 17.9648 79.3347 21.5619 82.5849 25.841C84.9175 28.9121 86.7997 32.2913 88.1811 35.8758C89.083 38.2158 91.5421 39.6781 93.9676 39.0409Z"
            fill="currentFill"
          />
        </svg>
      </div>
      <template v-else>
        <div class="text-base font-semibold">
          {{ $t('sendCurrentLocation') }}
        </div>
        <div class="text-xs">
          {{ address }}
        </div>
      </template>
    </button>
  </vue-final-modal>
</template>

<style scoped>
.v-enter-active,
.v-leave-active {
  transition: opacity 0.2s ease-in-out;
}

.v-enter-from,
.v-leave-to {
  opacity: 0;
}
:deep(.mapdiv) > div > div {
  border-top-left-radius: 8px !important;
  border-top-right-radius: 8px !important;
  overflow: hidden;
}
